import type { CollectionId, Group, Note } from '@rosie-notes/schema';
import { useMemo } from 'react';
import { useAddNote } from '../hooks/use-add-note';
import { useGroups } from '../hooks/use-groups';
import { useNoteActions } from '../hooks/use-note-actions';
import { useNoteQuery } from '../hooks/use-note-query';
import { useShuffle } from '../hooks/use-shuffle';
import { useNavigate } from '../routing/use-route';
import { Breadcrumb, PageHeader } from './chrome';
import { GroupRow } from './home-view';
import { Icon } from './icons';
import {
  ago,
  NOTE_KIND_ICON,
  NOTE_KIND_LABEL,
  plural,
  SHARED_WITH_LABEL,
  sortLabel,
} from './labels';
import { Btn, Chip, Sep } from './primitives';
import { AddRow, List, Row, SkeletonRows } from './rail';
import { useShell } from './shell-context';
import { EmptyState, ErrorState, NotFoundState, OfflineBanner } from './states';
import { useToast } from './toasts';

/**
 * A group, at any depth.
 *
 * The screen is identical whether this group sits at the top or six levels down, and identical at
 * 1440px, 390px and 320px. Depth is carried by the breadcrumb above and the spine in Places, not
 * by the layout — which is the whole of the "one column, any depth" claim, and the reason there
 * is no tree in a sidebar to die at 320px.
 *
 * Two sections, both on the rail: subgroups, then notes. Each ends in an add row, because
 * creating a subgroup must not feel heavier than creating a note.
 */

export interface GroupViewProps {
  readonly groupId: string;
}

export function GroupView({ groupId }: GroupViewProps): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const shell = useShell();
  const toast = useToast();
  const draw = useShuffle();
  const add = useAddNote();

  const group = tree.byId.get(groupId);
  const settings = tree.settingsOf(groupId).effective;
  const subgroups = tree.children(groupId);

  // The group's own sort reaches the request, so "least read first" is answered by the server
  // rather than approximated here.
  const query = useMemo(
    () => ({ collectionId: groupId as CollectionId, sort: settings.sort, limit: 100 }),
    [groupId, settings.sort],
  );
  const notes = useNoteQuery(query);

  if (group === undefined) {
    if (tree.loading) {
      return <SkeletonRows count={5} />;
    }
    return <NotFoundState onBack={() => navigate({ name: 'home' })} what="That group" />;
  }

  const counted = tree.tally(groupId);
  const chain = tree.chain(groupId);

  async function pullOne(): Promise<void> {
    const result = await draw(groupId, settings.shuffle);
    if (result.note === null) {
      toast.show('Nothing here to pull from yet.');
      return;
    }
    navigate({ name: 'note', noteId: result.note.id as string });
    toast.show(result.local ? 'Picked from this device.' : 'Picked one.', { icon: 'shuffle' });
  }

  async function addNote(): Promise<void> {
    const noteId = await add(groupId);
    navigate({ name: 'note', noteId });
  }

  const chips: React.JSX.Element[] = [];
  // Who can see it, named as an audience. Never how it is stored.
  if (settings.sharedWith === 'nobody') {
    chips.push(
      <Chip key="who" tone="line">
        Only you
      </Chip>,
    );
  } else {
    chips.push(
      <Chip icon="people" key="who" tone="accent">
        {SHARED_WITH_LABEL[settings.sharedWith]}
      </Chip>,
    );
  }
  if (settings.privateNotes) {
    chips.push(
      <Chip icon="lock" key="lock" tone="private">
        Locking on
      </Chip>,
    );
  }
  if (settings.readingMode) {
    chips.push(
      <Chip icon="book" key="reading">
        Reading mode
      </Chip>,
    );
  }
  if (settings.codeProject.enabled) {
    chips.push(
      <Chip key="project" tone="mono">
        {settings.codeProject.projectType ?? 'project'}
      </Chip>,
    );
  }

  return (
    <>
      <Breadcrumb
        chain={chain}
        onHome={() => navigate({ name: 'home' })}
        onOpen={(ancestor) => navigate({ name: 'group', groupId: ancestor.id as string })}
      />
      <PageHeader
        actions={
          <>
            <Btn
              className="wide-only"
              icon="plus"
              onClick={() => shell.openAdd(groupId)}
              tone="primary"
            >
              Add
            </Btn>
            {settings.shuffle !== 'off' && (
              <Btn icon="shuffle" onClick={() => void pullOne()} tone="ghost">
                Shuffle
              </Btn>
            )}
            <Btn
              icon="gear"
              onClick={() => navigate({ name: 'groupSettings', groupId })}
              tone="ghost"
            >
              Settings
            </Btn>
          </>
        }
        icon={group.icon}
        sub={chips}
        title={group.name}
      />

      {tree.stale && <OfflineBanner what="groups" />}
      {notes.stale && !tree.stale && <OfflineBanner what="notes" />}

      {subgroups.length === 0 && notes.notes.length === 0 && !notes.loading ? (
        <EmptyState
          action={
            <Btn icon="plus" large onClick={() => void addNote()} tone="primary">
              Add a note
            </Btn>
          }
          alt={
            <Btn onClick={() => navigate({ name: 'newGroup', parentId: groupId })} tone="quiet">
              or add a subgroup
            </Btn>
          }
          body="Start writing. You can sort it into subgroups later, or never."
          title={`Nothing in ${group.name} yet`}
        />
      ) : (
        <>
          {/* A real `<h2>` rather than a styled `<span>`. These two labels are the only way to
              tell the two lists apart, and as spans a screen-reader user could not jump to
              either one — the whole screen was a single unbroken region under its `<h1>`. */}
          <section className="sec">
            <div className="sec-head">
              <h2 className="sec-title">
                {settings.codeProject.enabled ? 'Folders' : 'Subgroups'}
              </h2>
              {subgroups.length > 0 && <span className="sec-note num">{subgroups.length}</span>}
            </div>
            <List label="Subgroups">
              {subgroups.map((child) => (
                <GroupRow group={child} key={child.id} />
              ))}
              <AddRow
                label="New subgroup"
                onClick={() => navigate({ name: 'newGroup', parentId: groupId })}
              />
            </List>
          </section>

          <section className="sec">
            <div className="sec-head">
              <h2 className="sec-title">Notes</h2>
              <span className="sec-note num">{sortLabel(settings.sort)}</span>
            </div>
            {notes.loading && notes.notes.length === 0 ? (
              <SkeletonRows count={3} />
            ) : notes.error !== null ? (
              <ErrorState
                body="The server did not answer and this device has nothing cached for this group."
                onRetry={notes.reload}
                title="These notes could not be loaded"
              />
            ) : (
              <List label="Notes">
                {notes.notes.map((note) => (
                  <NoteRow group={group} key={note.id} note={note} onChanged={notes.reload} />
                ))}
                <AddRow label="New note" onClick={() => void addNote()} />
              </List>
            )}
            {notes.hasMore && (
              <div className="undertext">
                <Btn onClick={notes.loadMore} small tone="quiet">
                  Show more
                </Btn>
              </div>
            )}
          </section>
        </>
      )}

      <p className="undertext">{plural(counted.notes, 'note')} in here and everything under it.</p>
    </>
  );
}

/**
 * One note, on the rail.
 *
 * The lock is a trailing control rather than something behind a menu, because per-note privacy is
 * the highest-stakes control in the product and the brief asks for it to be one tap. It only
 * appears when the group allows locking, so a group where it means nothing does not carry it.
 */
export function NoteRow({
  note,
  group,
  showPath = false,
  onChanged,
}: {
  readonly note: Note;
  readonly group?: Group | undefined;
  readonly showPath?: boolean;
  /** Called after a write that changes what this row shows, so the listing can catch up. */
  readonly onChanged?: () => void;
}): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const settings = tree.settingsOf((group?.id as string | undefined) ?? null).effective;

  // Privacy is modelled as a tag until the API carries a first-class flag; see the seam note in
  // the report. The word and the mark are driven from one place either way.
  const isPrivate = note.tags.includes('private' as Note['tags'][number]);
  const canLock = group !== undefined && settings.privateNotes;

  const meta: React.JSX.Element[] = [];
  if (isPrivate) {
    meta.push(
      <Chip icon="lock" key="private" tone="private">
        Private
      </Chip>,
    );
  }
  if (showPath) {
    const path = tree
      .chain((note.collectionIds[0] as string | undefined) ?? null)
      .map((entry) => entry.name)
      .join(' / ');
    if (path !== '') meta.push(<span key="path">{path}</span>);
  }
  meta.push(<span key="kind">{NOTE_KIND_LABEL[note.kind]}</span>);
  meta.push(<span key="ago">{ago(note.updatedAt)}</span>);

  return (
    <Row
      icon={<Icon name={NOTE_KIND_ICON[note.kind]} />}
      kind="note"
      label={note.title === '' ? 'Untitled' : note.title}
      mark={isPrivate ? 'private' : 'none'}
      meta={meta.flatMap((node, index) =>
        index === 0 ? [node] : [<Sep key={`sep-${node.key ?? index}`} />, node],
      )}
      onOpen={() => navigate({ name: 'note', noteId: note.id as string })}
      title={note.title === '' ? 'Untitled' : note.title}
      trailing={
        canLock ? (
          <LockButton isPrivate={isPrivate} note={note} onChanged={onChanged} />
        ) : (
          <Icon name="chev" />
        )
      }
      excerpt={note.excerpt}
    />
  );
}

/**
 * The per-note lock, as a trailing control on the row.
 *
 * `useNoteQuery` holds its own page of notes rather than reading through the store — deliberately,
 * so a tag click cannot make the list under an open editor jump. The cost is that a write made
 * from a row does not reach that page on its own, so the row tells its listing to catch up.
 */
function LockButton({
  note,
  isPrivate,
  onChanged,
}: {
  readonly note: Note;
  readonly isPrivate: boolean;
  readonly onChanged?: (() => void) | undefined;
}): React.JSX.Element {
  const actions = useNoteActions();
  const toast = useToast();

  return (
    <button
      aria-pressed={isPrivate}
      className="lockbtn"
      onClick={(event) => {
        // The row underneath is a click target too; locking a note must not also open it.
        event.stopPropagation();
        const next = isPrivate
          ? note.tags.filter((tag) => tag !== 'private')
          : [...note.tags, 'private' as Note['tags'][number]];
        void actions.setTags(note.id, next).then(() => {
          toast.show(isPrivate ? 'Unlocked.' : 'Locked.', {
            tone: 'brass',
            icon: isPrivate ? 'unlock' : 'lock',
          });
          onChanged?.();
        });
      }}
      title={isPrivate ? 'Private — only you' : 'Visible to everyone in this group'}
      type="button"
    >
      <Icon name={isPrivate ? 'lock' : 'unlock'} />
      <span className="sr">{isPrivate ? 'Unlock this note' : 'Make this note private'}</span>
    </button>
  );
}
