import type { GroupSettings, ScaffoldPlan } from '@rosie-notes/schema';
import { buildScaffoldPlan } from '@rosie-notes/schema';
import { useState } from 'react';
import { useGroupsOptional } from '../hooks/use-groups';
import { useUserConfig } from '../hooks/use-user-config';
import { Icon } from './icons';
import { Btn, Callout, SetRow, Sheet } from './primitives';

/**
 * What this project would consist of on disk — shown, never done.
 *
 * The constraint, in Rose's words (`NEXT-ROUND.md` §0b): *"nothing touches the disk until the user
 * says so — opening a shared project must never silently create directories on someone's
 * machine."* So this is a preview and there is no button here that creates anything. The web app
 * has no filesystem at all; the editor does, and that is where **Add to codebase** lives.
 *
 * The plan is computed with the same pure function the server runs
 * (`buildScaffoldPlan`), which is what lets it work on the *new group* screen — where there is no
 * group to ask the server about yet — and offline, and still agree with
 * `GET /v1/groups/:id/scaffold` to the character.
 *
 * Every line says **where it came from**. That is not decoration: a tag quietly redirecting a
 * project into a different root is exactly the thing somebody has to be able to see before they
 * agree to it.
 */

const SOURCE_LABEL: Record<ScaffoldPlan['actions'][number]['origin']['source'], string> = {
  'project-type': 'from the project type',
  subgroup: 'a subgroup',
  config: 'from your default folders',
  tag: 'added by the tag',
  'main-file': 'the main file',
};

export interface ScaffoldPreviewProps {
  readonly settings: GroupSettings;
  /** The group being edited, so its subgroups become folders. Absent on the new-group screen. */
  readonly groupId?: string | undefined;
  readonly groupName: string;
}

export function ScaffoldPreviewRow({
  settings,
  groupId,
  groupName,
}: ScaffoldPreviewProps): React.JSX.Element {
  const { config } = useUserConfig();
  const tree = useGroupsOptional();
  const [open, setOpen] = useState(false);

  const subgroups =
    groupId === undefined || tree === null ? [] : tree.children(groupId).map((group) => group.name);

  const plan = buildScaffoldPlan({
    config,
    codeProject: settings.codeProject,
    subgroups,
    groupName,
  });

  const folders = plan.actions.filter((action) => action.kind === 'directory').length;
  const files = plan.actions.length - folders;

  return (
    <>
      <SetRow
        help="Shows the folders and files this project would be made of. Nothing is created by looking."
        label="What this would create"
        onClick={() => setOpen(true)}
        value={
          <span>
            {plan.root === null ? 'Not worked out yet' : `${folders} folders, ${files} files`}
          </span>
        }
      />

      {open && (
        <Sheet
          onClose={() => setOpen(false)}
          sub={
            plan.root === null
              ? 'There is not enough here to work a folder out from yet.'
              : plan.root
          }
          title="What this would create"
        >
          {plan.warnings.length > 0 && (
            <div style={{ display: 'grid', gap: 8, marginBottom: 12 }}>
              {plan.warnings.map((warning) => (
                <p className="banner" key={warning} role="status">
                  <Icon name="warn" />
                  <span>{warning}</span>
                </p>
              ))}
            </div>
          )}

          {plan.actions.length === 0 ? (
            <p className="setrow-help">
              Nothing yet. Set a project type — and a project name if this group is not called what
              the folder should be — and this fills in.
            </p>
          ) : (
            <ul style={{ listStyle: 'none', margin: 0, padding: 0 }}>
              {plan.actions.map((action) => (
                <li className="setrow" key={action.path}>
                  <span className="setrow-main">
                    <span className="setrow-label chip-mono">{action.path}</span>
                    <span className="setrow-help">
                      {action.kind === 'file' ? 'File · ' : 'Folder · '}
                      {SOURCE_LABEL[action.origin.source]}
                      {action.origin.detail === null ? '' : ` ${action.origin.detail}`}
                    </span>
                  </span>
                </li>
              ))}
            </ul>
          )}

          {/* The whole reason this screen is a preview. The web app cannot write to a disk, and
              saying so plainly is better than a disabled button somebody keeps pressing. */}
          <Callout className="callout-spaced" icon="eye" tone="quiet">
            <b>Nothing here is created until you ask for it.</b> A browser cannot write to your disk
            at all. Open the project in the editor extension and use <b>Add to codebase</b>, which
            creates exactly this list and nothing else.
          </Callout>

          <div className="form__actions" style={{ marginTop: 16 }}>
            <Btn onClick={() => setOpen(false)} tone="ghost">
              Close
            </Btn>
          </div>
        </Sheet>
      )}
    </>
  );
}
