import { useEffect, useRef, useSyncExternalStore } from 'react';

/**
 * Is the browser reachable?
 *
 * `navigator.onLine` is a hint, not a fact — it says the machine has a network interface, not
 * that the API is answering — so nothing in the app *decides* anything from it. It is used for
 * exactly two things: choosing the word on the status badge before a request has failed, and
 * knowing when to try flushing the queue again. The authority on whether the server is there
 * remains "did the last request work".
 */

function subscribe(onChange: () => void): () => void {
  globalThis.addEventListener('online', onChange);
  globalThis.addEventListener('offline', onChange);
  return () => {
    globalThis.removeEventListener('online', onChange);
    globalThis.removeEventListener('offline', onChange);
  };
}

function snapshot(): boolean {
  return globalThis.navigator?.onLine ?? true;
}

export function useOnline(): boolean {
  return useSyncExternalStore(subscribe, snapshot, () => true);
}

/**
 * Run something whenever the browser says the network came back.
 *
 * Separate from {@link useOnline} because it must fire on the *event*, not on a change in the
 * flag. A machine that was never `offline` — a laptop on wi-fi whose server was down — still gets
 * an `online` event when the interface flaps, and that is exactly the moment worth retrying.
 */
export function useReconnect(onReconnect: () => void): void {
  const latest = useRef(onReconnect);
  latest.current = onReconnect;

  useEffect(() => {
    const handler = (): void => latest.current();
    globalThis.addEventListener('online', handler);
    return () => globalThis.removeEventListener('online', handler);
  }, []);
}
