import { structureTally } from '@rosie-notes/schema';
import { useState } from 'react';
import { useTemplates } from '../hooks/use-templates';
import { useNavigate } from '../routing/use-route';
import { PageHeader } from './chrome';
import { Icon } from './icons';
import { Btn, Callout, Glyph, Sheet } from './primitives';
import { useToast } from './toasts';

/**
 * Starting points — the presets a new group is made from, and yours to change.
 *
 * The screen exists because of one sentence from Rose: *"alowing users to edit the default group
 * settings so whenever they make that group again it follows said setings"*. So the shipped six
 * are listed here as ordinary, editable things rather than as app furniture.
 *
 * **The promise this screen has to make plainly** is that editing one changes what the *next*
 * group starts as and nothing else. A person who suspects otherwise will not touch any of it, and
 * a person who assumes otherwise loses work — so the sentence is on the screen, not in a doc.
 */

export function TemplatesView(): React.JSX.Element {
  const templates = useTemplates();
  const navigate = useNavigate();
  const toast = useToast();
  const [naming, setNaming] = useState(false);
  const [draft, setDraft] = useState('');
  const [failure, setFailure] = useState<string | null>(null);

  async function add(): Promise<void> {
    const name = draft.trim();
    if (name === '') return;
    setFailure(null);
    try {
      const created = await templates.create({ name });
      setNaming(false);
      setDraft('');
      toast.show('Starting point created.');
      navigate({ name: 'template', templateId: created.id });
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'The server did not accept that name.');
    }
  }

  return (
    <>
      <PageHeader
        actions={
          <Btn onClick={() => setNaming(true)} tone="primary">
            New starting point
          </Btn>
        }
        sub={
          <span>
            What a new group begins as. Change any of them — it only ever affects the groups you
            make afterwards.
          </span>
        }
        title="Starting points"
      />

      {/* Not the usual offline banner: template edits are not queued, so the honest line is that
          this is the shipped list and the person's own versions are not in it. */}
      {templates.local && !templates.loading && (
        <p className="banner" role="status">
          <Icon name="cloudoff" />
          <span>
            These are the starting points the app ships with. The server is unreachable, so any of
            your own are missing from this list until it comes back.
          </span>
        </p>
      )}

      <div className="cards">
        {templates.items.map((template) => {
          const tally = structureTally(template.structure);
          return (
            <button
              className="card"
              key={template.id}
              onClick={() => navigate({ name: 'template', templateId: template.id })}
              type="button"
            >
              <div className="card-title">
                <span className="rowicon">
                  <Glyph icon={template.icon} />
                </span>
                <span>{template.name}</span>
                {!template.shipped && <span className="chip">Yours</span>}
              </div>
              <div className="card-sub">
                {template.description ?? 'No description.'}
                {tally.groups > 0 && ` Creates ${tally.groups} sections.`}
              </div>
            </button>
          );
        })}
      </div>

      <Callout className="callout-spaced" icon="eye" tone="quiet">
        <b>Editing one never changes a group you already made.</b> A starting point is copied when
        the group is created and nothing links back afterwards, so these are safe to rearrange.
      </Callout>

      {naming && (
        <Sheet
          onClose={() => setNaming(false)}
          sub="It starts as a plain group with nothing switched on. Everything is editable next."
          title="New starting point"
        >
          <input
            aria-label="Starting point name"
            className="field field-lg"
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') void add();
            }}
            placeholder="Rust project"
            value={draft}
          />
          {failure !== null && (
            <p className="banner banner-clay" role="alert">
              {failure}
            </p>
          )}
          <div className="form__actions" style={{ marginTop: 16 }}>
            <Btn onClick={() => setNaming(false)} tone="ghost">
              Cancel
            </Btn>
            <Btn disabled={draft.trim() === ''} onClick={() => void add()} tone="primary">
              Create
            </Btn>
          </div>
        </Sheet>
      )}
    </>
  );
}
