/**
 * The shell: one column, any depth, with two optional flanks.
 *
 * | Region | Appears | Holds |
 * |---|---|---|
 * | **Places** (232px, left) | ≥ 901px | Home / Search / Trash, the top-level groups, and the **"You are here" spine** |
 * | **Stage** (max 820px, centre) | always | the app |
 * | **Context** (288px, right) | ≥ 1161px | counts, who can see it, actions |
 * | **Tab bar** (bottom) | ≤ 900px | Home · Search · **+** · Shuffle · Settings |
 *
 * Wide screens do not change the navigation model, they only add flanks to it. Below 900px what
 * is left *is* the phone app, and that is also the VSCode panel — nothing is a reduced version of
 * anything, which is why there is one model to learn rather than two.
 *
 * Every layout decision resolves from the **viewport**, in CSS media queries, never from a stored
 * device type or a JS width check. A width read in JavaScript is wrong for one frame on every
 * resize and wrong forever if the tab is restored at another size.
 */

export interface AppShellProps {
  readonly route: Route;
  readonly theme: ThemeMode;
  readonly appearance: Appearance;
}

export function AppShell(props: AppShellProps): React.JSX.Element {
  return (
    <ToastProvider>
      <GroupsProvider>
        <Shell {...props} />
      </GroupsProvider>
    </ToastProvider>
  );
}

function Shell({ route, theme, appearance }: AppShellProps): React.JSX.Element {
  const tree = useGroups();
  // Both sheets are history entries, so Back closes what is on top of the screen before it moves
  // the screen underneath — which is what the phone's Back gesture and a thumb button assume.
  const add = useLayer<{ groupId: string | null }>();
  const move = useLayer<string>();
  const [menuOpen, setMenuOpen] = useState(false);

  const control = useMemo<ShellControl>(
    () => ({
      openAdd: (groupId) => add.open({ groupId }),
      openMove: (noteId) => move.open(noteId),
      appearance,
    }),
    [appearance, add.open, move.open],
  );

  // The group a screen belongs to. A note's group is not in its URL, so it is resolved here and
  // used for two things: which Places entry is current, and which colour the screen is painted in.
  const noteState = useNote(route.name === 'note' ? (route.noteId as NoteId) : null);
  const currentGroupId =
    routeGroupId(route) ??
    (route.name === 'note'
      ? ((noteState.note?.collectionIds[0] as string | undefined) ?? null)
      : null);

  const groupName = currentGroupId === null ? null : (tree.byId.get(currentGroupId)?.name ?? null);
  // What the narrow topbar says it is showing. A group's name where there is one, and the
  // screen's own name where there is not — "Notes" on the new-group screen was just wrong.
  const whereLabel = narrowTitle(route, groupName);

  useEffect(() => {
    globalThis.document.title = routeTitle(route, groupName);
  }, [route, groupName]);

  // A new screen starts at the top of itself.
  //
  // Without this the browser keeps the scroll offset across a hash change, and every long form
  // hands the next screen its own scroll position. Creating a group was the visible case: the
  // new-group form is tall, so `Create group` sits near the bottom of the document, and the group
  // that opened afterwards opened *scrolled past its own title, breadcrumb and toolbar* — it read
  // as a half-loaded page. It is keyed on the route's identity rather than the object, because
  // `useRoute` parses a fresh object out of the hash on every render.
  const routeKey = routeToHash(route);
  // biome-ignore lint/correctness/useExhaustiveDependencies: routeKey is the re-run trigger
  useEffect(() => {
    globalThis.scrollTo?.({ top: 0, left: 0, behavior: 'instant' });
  }, [routeKey]);

  // A group's colour reaches everything on its screen — rails, beads, the primary button — so a
  // dreams group looks unlike a code project at a glance. It falls back up the chain, then to the
  // app accent.
  const screenAccent = tree.colourOf(currentGroupId);

  return (
    <ShellProvider value={control}>
      <div
        data-accent={appearance.accent}
        data-density={appearance.density}
        data-hover={appearance.hover}
        data-rn=""
        data-theme={theme}
      >
        {/* Every icon in the app is a `<use>` into this. Without it in the DOM they all resolve
            to nothing and the interface silently loses its glyphs. */}
        <IconSprite />
        <div className="shell">
          <Topbar
            menuOpen={menuOpen}
            onToggleMenu={() => setMenuOpen((open) => !open)}
            route={route}
            title={whereLabel}
          />

          <div className="frame">
            <Places currentGroupId={currentGroupId} route={route} />

            <main className="stage">
              <div className="stage-inner" data-gc={screenAccent ?? undefined}>
                <OutboxBanner />
                <Screen route={route} theme={theme} />
              </div>
            </main>

            <ContextColumn currentGroupId={currentGroupId} route={route} />
          </div>

          <TabBar currentGroupId={currentGroupId} route={route} />
        </div>

        {add.value !== null && (
          <AddSheet
            groupId={add.value.groupId}
            onClose={add.close}
            onCloseForNavigation={add.closeForNavigation}
          />
        )}
        {move.value !== null && <MoveSheet noteId={move.value} onClose={move.close} />}
      </div>
    </ShellProvider>
  );
}

function Screen({
  route,
  theme,
}: {
  readonly route: Route;
  readonly theme: ThemeMode;
}): React.JSX.Element {
  const navigate = useNavigate();

  switch (route.name) {
    case 'home':
      return <HomeView />;
    case 'group':
      return <GroupView groupId={route.groupId} />;
    case 'groupSettings':
      return <GroupSettingsView groupId={route.groupId} />;
    case 'newGroup':
      return <NewGroupView parentId={route.parentId} />;
    case 'note':
      return <NoteView noteId={route.noteId} theme={theme} />;
    case 'search':
      return <SearchView query={route.query} />;
    case 'trash':
      return <TrashView />;
    case 'settings':
      return <SettingsView />;
    case 'templates':
      return <TemplatesView />;
    case 'template':
      return <TemplateView templateId={route.templateId} />;
    default:
      return <NotFoundState onBack={() => navigate({ name: 'home' })} />;
  }
}

/** The name of where you are, for the narrow topbar. */
function narrowTitle(route: Route, groupName: string | null): string {
  switch (route.name) {
    case 'group':
    case 'groupSettings':
    case 'note':
      return groupName ?? 'Notes';
    case 'newGroup':
      return groupName === null ? 'New group' : `New group in ${groupName}`;
    case 'search':
      return 'Search';
    case 'trash':
      return 'Trash';
    case 'settings':
      return 'Settings';
    case 'templates':
    case 'template':
      return 'Starting points';
    default:
      return 'Notes';
  }
}

/**
 * The topbar.
 *
 * On a narrow screen it turns into a back control plus where you are — which is the same
 * drill-down stack the wide layout has, wearing the chrome a phone expects. The back control goes
 * **up one level**, not back in history: those differ the moment somebody arrives by a link, and
 * "up" is the one that is always meaningful.
 */
function Topbar({
  route,
  title,
  menuOpen,
  onToggleMenu,
}: {
  readonly route: Route;
  readonly title: string | null;
  readonly menuOpen: boolean;
  readonly onToggleMenu: () => void;
}): React.JSX.Element {
  const navigate = useNavigate();
  const tree = useGroups();
  const [query, setQuery] = useState('');

  useEffect(() => {
    if (route.name === 'search') setQuery(route.query);
  }, [route]);

  const atHome = route.name === 'home';

  function goUp(): void {
    const groupId = routeGroupId(route);
    if (groupId !== null) {
      const parent = tree.byId.get(groupId)?.parentId;
      navigate(
        parent === null || parent === undefined
          ? { name: 'home' }
          : { name: 'group', groupId: parent as string },
      );
      return;
    }
    navigate({ name: 'home' });
  }

  return (
    <header className="topbar">
      {/* Wide screens keep the brand and let Places carry "where am I". Narrow ones turn the bar
          into the drill-down's own chrome: up one level, and the name of where you are. Both are
          rendered and the viewport picks, so nothing depends on a width read in JavaScript. */}
      <div className="bar-lead">
        <div className={atHome ? 'brand' : 'brand wide-only'}>
          <span className="brand-tick" />
          <b>rosie</b>
          <span>notes</span>
        </div>
        {!atHome && (
          <>
            <button
              className="iconbtn only-narrow-flex"
              onClick={goUp}
              title="Up one level"
              type="button"
            >
              <Icon name="chevl" />
              <span className="sr">Up one level</span>
            </button>
            <div className="brand brand-here only-narrow">
              <b>{title ?? 'Notes'}</b>
            </div>
          </>
        )}
      </div>

      <div className="topbar-search">
        <Icon name="search" />
        <input
          aria-label="Search every note"
          onChange={(event) => {
            setQuery(event.target.value);
            navigate(
              { name: 'search', query: event.target.value },
              { replace: route.name === 'search' },
            );
          }}
          placeholder="Search every note"
          type="search"
          value={query}
        />
      </div>

      <div className="topbar-end">
        <button
          className="iconbtn only-narrow-flex"
          onClick={() => navigate({ name: 'search', query: '' })}
          title="Search every note"
          type="button"
        >
          <Icon name="search" />
          <span className="sr">Search</span>
        </button>
        <div className="menu-wrap">
          <button
            aria-expanded={menuOpen}
            className="iconbtn"
            onClick={onToggleMenu}
            title="Theme, density and accent"
            type="button"
          >
            <Icon name="sun" />
            <span className="sr">Appearance</span>
          </button>
          {menuOpen && <AppearanceMenu onClose={onToggleMenu} />}
        </div>
        <button
          className="iconbtn"
          onClick={() => navigate({ name: 'settings' })}
          title="Settings"
          type="button"
        >
          <Icon name="gear" />
          <span className="sr">Settings</span>
        </button>
      </div>
    </header>
  );
}

/**
 * Places, and the spine.
 *
 * The top half is the fixed destinations and the top-level groups. The bottom half is the **"You
 * are here" spine**: the rail turned vertical, one bead per level of the descent, so the whole
 * path is visible at once on a screen wide enough to show it. It is not a tree — it shows the
 * branch you are standing on, not every branch, which is what keeps arbitrary depth legible
 * without a disclosure triangle in sight.
 */
function Places({
  route,
  currentGroupId,
}: {
  readonly route: Route;
  readonly currentGroupId: string | null;
}): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const chain = tree.chain(currentGroupId);

  return (
    <nav aria-label="Places" className="places">
      <div className="places-label">Places</div>
      <button
        aria-current={route.name === 'home'}
        className="place"
        onClick={() => navigate({ name: 'home' })}
        type="button"
      >
        <Icon name="home" />
        <span className="place-name">Home</span>
      </button>
      <button
        aria-current={route.name === 'search'}
        className="place"
        onClick={() => navigate({ name: 'search', query: '' })}
        type="button"
      >
        <Icon name="search" />
        <span className="place-name">Search</span>
      </button>
      <button
        aria-current={route.name === 'trash'}
        className="place"
        onClick={() => navigate({ name: 'trash' })}
        type="button"
      >
        <Icon name="trash" />
        <span className="place-name">Trash</span>
      </button>

      <div className="places-label">Groups</div>
      {tree.roots.map((group) => (
        <button
          aria-current={chain[0]?.id === group.id}
          className="place"
          data-gc={accentFromColour(group.colour) ?? undefined}
          key={group.id}
          onClick={() => navigate({ name: 'group', groupId: group.id as string })}
          type="button"
        >
          <span className="place-glyph">
            <Glyph icon={group.icon} />
          </span>
          <span className="place-name">{group.name}</span>
          <span className="count num">{tree.tally(group.id as string).notes}</span>
        </button>
      ))}
      {tree.roots.length === 0 && (
        <p className="setrow-help" style={{ padding: '4px 10px' }}>
          No groups yet.
        </p>
      )}

      {chain.length > 1 && (
        <>
          <div className="places-label">You are here</div>
          <div className="spine">
            <button className="spine-step" onClick={() => navigate({ name: 'home' })} type="button">
              <span className="bead" />
              <span className="lbl">Home</span>
            </button>
            {chain.map((group, index) => (
              <button
                className={index === chain.length - 1 ? 'spine-step here' : 'spine-step'}
                key={group.id}
                onClick={() => navigate({ name: 'group', groupId: group.id as string })}
                type="button"
              >
                <span className="bead" />
                <span className="lbl">{group.name}</span>
              </button>
            ))}
          </div>
        </>
      )}
    </nav>
  );
}

/** Counts, who can see it, and the actions that do not belong in the header. */
function ContextColumn({
  route,
  currentGroupId,
}: {
  readonly route: Route;
  readonly currentGroupId: string | null;
}): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const sync = useSyncStatus();

  const group = currentGroupId === null ? undefined : tree.byId.get(currentGroupId);

  return (
    <aside aria-label="About this" className="context">
      {group === undefined ? (
        <div className="ctx-block">
          <div className="ctx-label">Everything</div>
          <div className="ctx-stat">
            <span>Groups</span>
            <b className="num">{tree.byId.size}</b>
          </div>
          <div className="ctx-stat">
            <span>Sync</span>
            <b style={{ color: sync === 'error' ? 'var(--clay)' : 'var(--sage)' }}>
              {sync === 'error' ? 'Not right now' : 'Up to date'}
            </b>
          </div>
        </div>
      ) : (
        <>
          <div className="ctx-block">
            <div className="ctx-label">This group</div>
            <div className="ctx-stat">
              <span>Subgroups</span>
              <b className="num">{tree.tally(currentGroupId as string).groups}</b>
            </div>
            <div className="ctx-stat">
              <span>Notes</span>
              <b className="num">{tree.tally(currentGroupId as string).notes}</b>
            </div>
            <div className="ctx-stat">
              <span>Last change</span>
              <b className="num">{ago(group.updatedAt)}</b>
            </div>
          </div>

          {/* Who can see it, named as an audience. Never how it is stored. */}
          <div className="ctx-block">
            <div className="ctx-label">Who can see it</div>
            <p className="ctx-note">
              {tree.settingsOf(currentGroupId).effective.sharedWith === 'nobody'
                ? 'Only you.'
                : SHARED_WITH_LABEL[tree.settingsOf(currentGroupId).effective.sharedWith]}
            </p>
            <p className="setrow-help">
              Whoever runs the server can read what is on it, whatever this says.
            </p>
          </div>

          <div className="ctx-block">
            <div className="ctx-label">Do</div>
            <div className="ctx-actions">
              <Btn
                icon="gear"
                onClick={() =>
                  navigate({ name: 'groupSettings', groupId: currentGroupId as string })
                }
                tone="ghost"
              >
                Group settings
              </Btn>
              {route.name !== 'newGroup' && (
                <Btn
                  icon="plus"
                  onClick={() => navigate({ name: 'newGroup', parentId: currentGroupId as string })}
                  tone="ghost"
                >
                  New subgroup
                </Btn>
              )}
            </div>
          </div>
        </>
      )}
    </aside>
  );
}

/** Home · Search · **+** · Shuffle · Settings. Below 900px this is the whole of navigation. */
function TabBar({
  route,
  currentGroupId,
}: {
  readonly route: Route;
  readonly currentGroupId: string | null;
}): React.JSX.Element {
  const navigate = useNavigate();
  const shell = useShell();

  return (
    <nav aria-label="Main" className="tabbar">
      <button
        aria-current={route.name === 'home'}
        className="tab"
        onClick={() => navigate({ name: 'home' })}
        type="button"
      >
        <Icon name="home" />
        <span>Home</span>
      </button>
      <button
        aria-current={route.name === 'search'}
        className="tab"
        onClick={() => navigate({ name: 'search', query: '' })}
        type="button"
      >
        <Icon name="search" />
        <span>Search</span>
      </button>
      <button
        className="tab tab-add"
        onClick={() => shell.openAdd(currentGroupId)}
        title="Add"
        type="button"
      >
        <span>
          <Icon name="plus" />
        </span>
        <span className="sr">Add</span>
      </button>
      <button
        aria-current={route.name === 'trash'}
        className="tab"
        onClick={() => navigate({ name: 'trash' })}
        type="button"
      >
        <Icon name="trash" />
        <span>Trash</span>
      </button>
      <button
        aria-current={route.name === 'settings'}
        className="tab"
        onClick={() => navigate({ name: 'settings' })}
        type="button"
      >
        <Icon name="gear" />
        <span>Settings</span>
      </button>
    </nav>
  );
}

/**
 * The add flow's first step: a note, or a group.
 *
 * "A note is a thing you write. A group holds notes and other groups." Two cards, equal weight —
 * because making a subgroup must not feel heavier than making a note. The note card names what a
 * new note will actually *be* in this group, read out of its settings, so the preset is visible
 * as consequences rather than as a label.
 */
function AddSheet({
  groupId,
  onClose,
  onCloseForNavigation,
}: {
  readonly groupId: string | null;
  readonly onClose: () => void;
  /** Use when leaving the sheet for another screen — see `closeForNavigation` in use-layer. */
  readonly onCloseForNavigation: () => void;
}): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const add = useAddNote();
  const group = groupId === null ? undefined : tree.byId.get(groupId);
  const settings = tree.settingsOf(groupId).effective;

  async function addNote(): Promise<void> {
    const noteId = await add(groupId);
    onCloseForNavigation();
    navigate({ name: 'note', noteId: noteId as string }, { replace: true });
  }

  return (
    <Sheet
      onClose={onClose}
      sub="A note is a thing you write. A group holds notes and other groups."
      title={`Add to ${group?.name ?? 'your notes'}`}
    >
      <div className="cards">
        <button className="card" onClick={() => void addNote()} type="button">
          <div className="card-title">
            <span className="rowicon">
              <Icon name="edit" />
            </span>
            <span>Add a note</span>
          </div>
          <div className="card-sub">
            Starts as a {settings.newNoteKind === 'page' ? 'blank page' : settings.newNoteKind}
            {settings.autoTitle.enabled ? ', named automatically' : ''}.
          </div>
        </button>
        <button
          className="card"
          onClick={() => {
            onCloseForNavigation();
            navigate({ name: 'newGroup', parentId: groupId }, { replace: true });
          }}
          type="button"
        >
          <div className="card-title">
            <span className="rowicon">
              <Icon name="box" />
            </span>
            <span>Add a group</span>
          </div>
          <div className="card-sub">
            {group === undefined
              ? 'Start from a preset, or from nothing.'
              : `Takes its settings from ${group.name}.`}
          </div>
        </button>
      </div>
    </Sheet>
  );
}

/**
 * Moving a note.
 *
 * **A note lives in exactly one group**, so this is a replace rather than an add — which is why
 * it is a flat list of every group with its path spelled out, not a tree with checkboxes. There
 * is one right answer and the picker should look like there is.
 */
function MoveSheet({
  noteId,
  onClose,
}: {
  readonly noteId: string;
  readonly onClose: () => void;
}): React.JSX.Element {
  const tree = useGroups();
  const actions = useNoteActions();
  const toast = useToast();
  const { note } = useNote(noteId as NoteId);
  const currentGroupId = (note?.collectionIds[0] as string | undefined) ?? null;

  const all = useMemo(() => {
    const out: { group: Group; path: string }[] = [];
    for (const group of tree.byId.values()) {
      out.push({
        group,
        path: tree
          .chain(group.id as string)
          .map((entry) => entry.name)
          .join(' / '),
      });
    }
    return out.sort((left, right) => left.path.localeCompare(right.path));
  }, [tree]);

  const move = useCallback(
    async (target: Group) => {
      await actions.update(noteId as NoteId, { collectionIds: [target.id] });
      toast.show(`Moved to ${target.name}.`, { icon: 'move' });
      onClose();
    },
    [actions, noteId, onClose, toast],
  );

  return (
    <Sheet
      onClose={onClose}
      sub="A note lives in exactly one group. Moving it takes its settings, sharing and quick tags from wherever it lands."
      title="Move this note"
    >
      {all.length === 0 ? (
        <p className="setrow-help">There are no groups to move it into yet.</p>
      ) : (
        <div className="setlist">
          {all.map(({ group, path }) => (
            <button
              className="setrow"
              disabled={group.id === currentGroupId}
              key={group.id}
              onClick={() => void move(group)}
              type="button"
            >
              <span className="setrow-main">
                <span className="setrow-label">{group.name}</span>
                <span className="setrow-help">{path}</span>
              </span>
              <span className="setrow-value">
                {group.id === currentGroupId ? (
                  <span className="inh inh-here">Here now</span>
                ) : null}
                <Icon className="chev" name="chev" />
              </span>
            </button>
          ))}
        </div>
      )}
    </Sheet>
  );
}

/**
 * Writes waiting in the outbox, shown on every screen because it is about the whole app.
 *
 * This is also where the queue is drained on reconnect. `navigator.onLine` is a hint rather than
 * a fact — it says the machine has an interface, not that the API is answering — so nothing
 * *decides* anything from it. It is only the moment worth retrying, and a failed retry simply
 * leaves the queue where it was.
 */
function OutboxBanner(): React.JSX.Element | null {
  const pending = usePendingWrites();
  const workspace = useWorkspace();

  useReconnect(() => {
    void workspace.flush().catch(() => undefined);
  });

  if (pending === 0) return null;
  return <PendingWritesBanner count={pending} />;
}
