import type { KeyboardEvent, ReactNode } from 'react';
import { Icon } from './icons';

/**
 * The rail: one hairline down the left of every list, with beads on it.
 *
 * This is the product's signature element and the only decorative-looking thing in it that is not
 * decoration. Because every row's status sits on one vertical line at a fixed x-position, forty
 * dream entries can be scanned for which ones are locked without reading a single word — which is
 * the acceptance test from the brief, answered by the signature element rather than by a badge
 * bolted on somewhere.
 *
 * Four marks, and each is paired with a word elsewhere in the row so none of them is colour
 * alone:
 *
 * | Mark | Means | Also says |
 * |---|---|---|
 * | a branch crossing the rail | a group | serif title, subgroup/note counts |
 * | a filled bead | unread | a counted chip |
 * | a brass lock | private | the word "Private", and a filled lock button |
 * | a ring | currently open | the row is tinted |
 */

export type RowMark = 'none' | 'group' | 'unread' | 'private' | 'open';

const MARK_CLASS: Record<RowMark, string> = {
  none: 'mark',
  group: 'mark m-group',
  unread: 'mark m-unread',
  private: 'mark m-private',
  open: 'mark m-open',
};

export function Mark({ mark }: { readonly mark: RowMark }): React.JSX.Element {
  if (mark === 'private') {
    return (
      <span className={MARK_CLASS.private} title="Private">
        <i>
          <Icon name="lock" />
        </i>
      </span>
    );
  }
  return (
    <span className={MARK_CLASS[mark]} title={mark === 'unread' ? 'New' : undefined}>
      <i />
    </span>
  );
}

export interface ListProps {
  readonly children: ReactNode;
  /** Drop the hairline. Used where a list is a single "add" affordance and has nothing to line up. */
  readonly noRail?: boolean;
  readonly label?: string;
}

/**
 * A real `<ul>`, with each row a real `<li>`.
 *
 * The rail is drawn on the list's own `::before`, so the semantics cost nothing visually and buy
 * the thing a labelled div could not: a screen reader announcing "list, 5 items" before the rows,
 * which is the audible equivalent of what the rail does for the eye.
 */
export function List({ children, noRail = false, label }: ListProps): React.JSX.Element {
  return (
    <ul aria-label={label} className={noRail ? 'list no-rail' : 'list'}>
      {children}
    </ul>
  );
}

export interface RowProps {
  readonly mark: RowMark;
  readonly title: ReactNode;
  readonly meta?: ReactNode;
  readonly excerpt?: ReactNode;
  readonly trailing?: ReactNode;
  readonly onOpen: () => void;
  readonly kind?: 'group' | 'note' | 'plain';
  readonly open?: boolean;
  /** The group's colour, when it owns one, so its rail and beads read in it. */
  readonly accent?: string | null;
  readonly icon?: ReactNode;
  /** The accessible name, when the visible title is not a plain string. */
  readonly label?: string;
}

/**
 * One row: rail bead, title and meta, trailing control.
 *
 * A `div` with `role="button"` rather than a `<button>`, because the trailing control is often
 * itself a button — a lock toggle — and a button inside a button is invalid and behaves
 * differently in every browser. The keyboard contract is honoured by hand instead: Enter and
 * Space both open, exactly as a button would.
 */
export function Row({
  mark,
  title,
  meta,
  excerpt,
  trailing,
  onOpen,
  kind = 'note',
  open = false,
  accent,
  icon,
  label,
}: RowProps): React.JSX.Element {
  const classes = ['row'];
  if (kind === 'group') classes.push('is-group');
  if (kind === 'note') classes.push('is-note');
  if (open) classes.push('is-open');

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>): void {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    // Space scrolls the page by default, which is exactly wrong on a row you meant to open.
    event.preventDefault();
    onOpen();
  }

  return (
    /*
     * The `<li>` is the list item; the control is the element inside it.
     *
     * That control is a `div` with `role="button"` rather than a `<button>`, because a row's
     * trailing control is often itself a button — the per-note lock — and a `<button>` inside a
     * `<button>` is invalid HTML that behaves differently in every engine. The keyboard contract
     * is honoured by hand instead: Enter and Space both open, exactly as a button would.
     */
    <li className="row-item">
      {/* biome-ignore lint/a11y/useSemanticElements: a <button> here would nest buttons */}
      <div
        aria-label={label}
        className={classes.join(' ')}
        data-gc={accent ?? undefined}
        onClick={onOpen}
        onKeyDown={onKeyDown}
        role="button"
        tabIndex={0}
      >
        <Mark mark={mark} />
        <span className="row-body">
          <span className={kind === 'plain' ? 'row-title plain' : 'row-title'}>
            {icon !== undefined && <span className="rowicon">{icon}</span>}
            <span className="row-title-text">{title}</span>
          </span>
          {excerpt !== undefined && excerpt !== '' && (
            <span className="row-excerpt">{excerpt}</span>
          )}
          {meta !== undefined && <span className="row-meta num">{meta}</span>}
        </span>
        <span className="row-trail">{trailing ?? <Icon name="chev" />}</span>
      </div>
    </li>
  );
}

/**
 * The last row of every list.
 *
 * Creating a subgroup is exactly as heavy as creating a note — one tap, in place, no modal. That
 * is the whole of flow 4.1 from the brief, and it is why this is a row rather than a button
 * somewhere else on the screen.
 */
export function AddRow({
  label,
  onClick,
}: {
  readonly label: string;
  readonly onClick: () => void;
}): React.JSX.Element {
  return (
    <Row
      kind="plain"
      label={label}
      mark="none"
      onOpen={onClick}
      title={label}
      trailing={<Icon name="plus" />}
    />
  );
}

/**
 * A list-shaped placeholder.
 *
 * A spinner over a list is a lie about what is coming; a few rail rows are the truth, and they
 * stop the page reflowing when the real thing lands.
 */
export function SkeletonRows({ count = 3 }: { readonly count?: number }): React.JSX.Element {
  return (
    <div aria-busy="true" className="list" role="status">
      <span className="sr">Loading…</span>
      {Array.from({ length: count }, (_unused, index) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: placeholders have no identity of their own
        <div className="skeleton-row" key={index}>
          <span />
          <span>
            <span className="skeleton-bar" style={{ width: `${70 - index * 12}%` }} />
            <span className="skeleton-bar" style={{ width: `${40 - index * 6}%` }} />
          </span>
        </div>
      ))}
    </div>
  );
}
