import type { Group } from '@rosie-notes/schema';
import { useGroups } from '../hooks/use-groups';
import { useNavigate } from '../routing/use-route';
import { PageHeader } from './chrome';
import { Icon } from './icons';
import { ago, plural } from './labels';
import { Btn, Chip, Glyph, Sep } from './primitives';
import { AddRow, List, Row, SkeletonRows } from './rail';
import { useShell } from './shell-context';
import { ErrorState, OfflineBanner } from './states';

/**
 * Home: every top-level group, and the way in to a new one.
 *
 * This is the front door and it is the same shape as every other level — a rail with rows on it,
 * and an add row at the bottom. That is the point of "one column, any depth": home is not a
 * special screen, it is the group list with no parent.
 */

export function HomeView(): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const shell = useShell();

  if (tree.error !== null && tree.roots.length === 0) {
    return (
      <ErrorState
        body="The server did not answer, and there is nothing cached on this device yet."
        onRetry={() => void tree.reload()}
        title="Your groups could not be loaded"
      />
    );
  }

  if (tree.loading && tree.roots.length === 0) {
    return (
      <>
        <PageHeader sub={<span>Counting things up…</span>} title="Your groups" />
        <SkeletonRows count={4} />
      </>
    );
  }

  const totals = tree.roots.reduce(
    (running, group) => {
      const counted = tree.tally(group.id as string);
      return { notes: running.notes + counted.notes, groups: running.groups + counted.groups + 1 };
    },
    { notes: 0, groups: 0 },
  );

  const lastChange = tree.roots
    .map((group) => group.updatedAt)
    .sort()
    .at(-1);

  if (tree.roots.length === 0) {
    // The empty state's single big button. A quiet text link offers the other action underneath,
    // so the primary one stays singular.
    return (
      <div className="empty">
        <div className="empty-mark" />
        {/* An `<h1>`, not the `<h2>` `EmptyState` uses: this one *replaces* the page header
            rather than sitting under it, and a screen with no `<h1>` at all is the same problem
            as a skipped level seen from the other end. */}
        <h1>Nothing here yet</h1>
        <p>
          Everything lives in a group — a project, a journal, a shelf of things to read. Make the
          first one and you can rearrange it later, or never.
        </p>
        <Btn
          icon="plus"
          large
          onClick={() => navigate({ name: 'newGroup', parentId: null })}
          tone="primary"
        >
          Add a group
        </Btn>
      </div>
    );
  }

  return (
    <>
      {tree.stale && <OfflineBanner what="groups" />}
      <PageHeader
        actions={
          <Btn className="wide-only" icon="plus" onClick={() => shell.openAdd(null)} tone="primary">
            Add
          </Btn>
        }
        sub={
          <>
            <span className="num">{plural(totals.notes, 'note')}</span>
            <Sep />
            <span className="num">
              {plural(totals.groups, 'group')}, {tree.roots.length} at the top
            </span>
            {lastChange !== undefined && (
              <>
                <Sep />
                <span>last change {ago(lastChange)}</span>
              </>
            )}
          </>
        }
        title="Your groups"
      />
      <List label="Your groups">
        {tree.roots.map((group) => (
          <GroupRow group={group} key={group.id} />
        ))}
        <AddRow label="New group" onClick={() => navigate({ name: 'newGroup', parentId: null })} />
      </List>
    </>
  );
}

/**
 * One group, on the rail.
 *
 * The meta line is the group's settings read back as words — how many things are in it, whether
 * it reads, who can see it. A person should be able to tell what a group *is* without opening it.
 */
export function GroupRow({ group }: { readonly group: Group }): React.JSX.Element {
  const tree = useGroups();
  const navigate = useNavigate();
  const counted = tree.tally(group.id as string);
  const settings = tree.settingsOf(group.id as string).effective;

  const meta: React.JSX.Element[] = [];
  if (counted.groups > 0) {
    meta.push(<span key="groups">{plural(counted.groups, 'subgroup')}</span>);
  }
  meta.push(<span key="notes">{plural(counted.notes, 'note')}</span>);
  if (settings.readingMode) {
    meta.push(
      <Chip icon="book" key="reading">
        Reading
      </Chip>,
    );
  }
  if (settings.sharedWith === 'specific_people') {
    meta.push(
      <Chip icon="people" key="shared" tone="accent">
        Shared
      </Chip>,
    );
  } else if (settings.sharedWith === 'anyone_with_link') {
    meta.push(
      <Chip key="link" tone="line">
        Anyone with the link
      </Chip>,
    );
  }
  if (settings.privateNotes) {
    meta.push(
      <Chip icon="lock" key="lock" tone="private">
        Locking on
      </Chip>,
    );
  }
  meta.push(<span key="ago">{ago(group.updatedAt)}</span>);

  return (
    <Row
      // A group with no colour of its own reads in its nearest coloured ancestor's, which is what
      // makes a whole project tree one colour rather than only its root row.
      accent={tree.colourOf(group.id as string)}
      icon={<Glyph icon={group.icon} />}
      kind="group"
      label={group.name}
      mark="group"
      meta={meta.flatMap((node, index) =>
        index === 0 ? [node] : [<Sep key={`sep-${node.key ?? index}`} />, node],
      )}
      onOpen={() => navigate({ name: 'group', groupId: group.id as string })}
      title={group.name}
      trailing={<Icon name="chev" />}
    />
  );
}
