import { useMemo } from 'react';
import { useNoteActions } from '../hooks/use-note-actions';
import { useNoteQuery } from '../hooks/use-note-query';
import { useNavigate } from '../routing/use-route';
import { PageHeader } from './chrome';
import { Icon } from './icons';
import { ago } from './labels';
import { Btn } from './primitives';
import { List, Row, SkeletonRows } from './rail';
import { EmptyState, ErrorState, OfflineBanner } from './states';
import { useToast } from './toasts';

/**
 * The trash.
 *
 * Restore is the primary action and purge is not offered per row: a list where "put it back" and
 * "destroy it for good" sit next to each other at the same weight is a list where somebody
 * eventually hits the wrong one. Purging is a deliberate second step.
 */

export function TrashView(): React.JSX.Element {
  const navigate = useNavigate();
  const actions = useNoteActions();
  const toast = useToast();

  const query = useMemo(
    () => ({
      filter: { type: 'flag' as const, flag: 'trashed' as const, value: true },
      limit: 100,
    }),
    [],
  );
  const notes = useNoteQuery(query);

  return (
    <>
      <PageHeader
        sub={<span>Notes stay here until you put them back or empty them out.</span>}
        title="Trash"
      />

      {notes.stale && <OfflineBanner what="trash" />}

      {notes.loading && notes.notes.length === 0 ? (
        <SkeletonRows count={3} />
      ) : notes.error !== null ? (
        <ErrorState
          body="The server did not answer and this device has nothing cached."
          onRetry={notes.reload}
          title="The trash could not be loaded"
        />
      ) : notes.notes.length === 0 ? (
        <EmptyState
          action={
            <Btn onClick={() => navigate({ name: 'home' })} tone="ghost">
              Back to your groups
            </Btn>
          }
          body="Nothing has been thrown away."
          title="The trash is empty"
        />
      ) : (
        <List label="Trashed notes">
          {notes.notes.map((note) => (
            <Row
              excerpt={note.excerpt}
              icon={<Icon name="trash" />}
              key={note.id}
              kind="note"
              label={note.title === '' ? 'Untitled' : note.title}
              mark="none"
              meta={<span>trashed {ago(note.trashedAt ?? note.updatedAt)}</span>}
              onOpen={() => navigate({ name: 'note', noteId: note.id as string })}
              title={note.title === '' ? 'Untitled' : note.title}
              trailing={
                <button
                  className="btn btn-sm"
                  onClick={(event) => {
                    event.stopPropagation();
                    void actions.restore(note.id).then(() => {
                      toast.show('Put back.');
                      notes.reload();
                    });
                  }}
                  type="button"
                >
                  Put back
                </button>
              }
            />
          ))}
        </List>
      )}
    </>
  );
}
