import type { UserConfig } from '@rosie-notes/schema';
import { EMPTY_USER_CONFIG } from '@rosie-notes/schema';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useWorkspace } from '../session/session-context';

/**
 * The signed-in person's own setup: project types, path templates and the file a new project gets.
 *
 * One document, read whole and replaced whole — a config is written as a file, so there is no
 * patch surface to keep in step with it.
 *
 * `configured` is the distinction that matters on screen: an account that has never saved one and
 * an account that saved an empty one are the same *values* but not the same *situation*, and only
 * one of them should be offered an import.
 */

export interface UserConfigState {
  readonly config: UserConfig;
  /** False until the server confirms a saved config exists. */
  readonly configured: boolean;
  readonly loading: boolean;
  reload(): Promise<void>;
  save(config: UserConfig): Promise<void>;
}

const CACHE_KEY = 'rosie-notes:user-config';

function readCache(): UserConfig | null {
  try {
    const raw = globalThis.localStorage?.getItem(CACHE_KEY);
    if (raw === null || raw === undefined) return null;
    return JSON.parse(raw) as UserConfig;
  } catch {
    return null;
  }
}

export function useUserConfig(): UserConfigState {
  const workspace = useWorkspace();
  const [config, setConfig] = useState<UserConfig>(() => readCache() ?? EMPTY_USER_CONFIG);
  const [configured, setConfigured] = useState(false);
  const [loading, setLoading] = useState(true);

  const reload = useCallback(async () => {
    setLoading(true);
    try {
      const response = await workspace.client.userConfig.get();
      setConfig(response.config);
      setConfigured(response.updatedAt !== null);
      try {
        globalThis.localStorage?.setItem(CACHE_KEY, JSON.stringify(response.config));
      } catch {
        // Over quota, or storage disabled. The next cold start simply waits for the network.
      }
    } catch {
      // Offline. Whatever was cached still resolves paths correctly, and an unsaved config is
      // reported as unsaved rather than as an error nobody can act on.
      setConfig(readCache() ?? EMPTY_USER_CONFIG);
    } finally {
      setLoading(false);
    }
  }, [workspace]);

  useEffect(() => {
    void reload();
  }, [reload]);

  return useMemo<UserConfigState>(
    () => ({
      config,
      configured,
      loading,
      reload,
      async save(next) {
        const response = await workspace.client.userConfig.replace(next);
        setConfig(response.config);
        setConfigured(true);
        try {
          globalThis.localStorage?.setItem(CACHE_KEY, JSON.stringify(response.config));
        } catch {
          // As above.
        }
      },
    }),
    [config, configured, loading, reload, workspace],
  );
}
