import { isClientError, type NotesClientError } from '@rosie-notes/client';
import type {
  CollectionId,
  Group,
  GroupCreateRequestInput,
  GroupSettings,
  GroupUpdateRequest,
  ResolvedGroupSettings,
} from '@rosie-notes/schema';
import { DEFAULT_GROUP_SETTINGS, resolveGroupSettings } from '@rosie-notes/schema';
import { type AccentName, accentFromColour } from '@rosie-notes/tokens';
import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';
import { useWorkspace } from '../session/session-context';

/**
 * The group tree, loaded once and held whole.
 *
 * Groups are nested to arbitrary depth, and three separate parts of the interface need *ancestors
 * of a group they have not visited*: the breadcrumb, the Places spine, and the group-colour
 * inheritance. Fetching one level at a time would mean a deep link into a group six levels down
 * paints a breadcrumb of spinners. `GET /v1/groups` with no `parentId` returns every group at
 * every depth, and groups are tens of rows, not thousands — so the whole tree is the right unit.
 *
 * Notes are emphatically *not* held here. They are the thousands, they page, and they live in
 * `NotesStore` and `useNoteQuery`.
 *
 * ## The cascade, resolved locally
 *
 * `resolveGroupSettings` is shared verbatim with the server, so once the chain is in hand the
 * effective values and their origins can be computed without a round trip — and cannot disagree
 * with what the server would have said. {@link useGroupSettings} still prefers the server's
 * answer when it has one; the local resolve is what makes the settings screen paint immediately
 * and what keeps it working offline.
 */

export interface GroupTree {
  readonly byId: ReadonlyMap<string, Group>;
  /** Top-level groups, in position order. */
  readonly roots: readonly Group[];
  readonly loading: boolean;
  readonly error: NotesClientError | null;
  /** True when this is the last known tree rather than a fresh one — the server is unreachable. */
  readonly stale: boolean;
  children(parentId: string | null): readonly Group[];
  /** Root first, this group last. What the breadcrumb and the spine both walk. */
  chain(groupId: string | null): readonly Group[];
  /** Notes and subgroups beneath a group, at every depth. */
  tally(groupId: string): { readonly notes: number; readonly groups: number };
  /**
   * The nearest accent up the chain — what `data-gc` on a screen wrapper resolves to.
   *
   * A group stores `#rrggbb`, because that is what the API validates, but `data-gc` takes one of
   * the six *names*: a name is what re-declares all five accent tokens for both themes, and a raw
   * hex would only ever be one of them. `accentFromColour` is the join.
   */
  colourOf(groupId: string | null): AccentName | null;
  /** Effective settings for a group, resolved from the chain this client already holds. */
  settingsOf(groupId: string | null): ResolvedGroupSettings;
  reload(): Promise<void>;
  create(input: GroupCreateRequestInput): Promise<Group>;
  update(id: CollectionId, patch: GroupUpdateRequest): Promise<Group>;
  remove(id: CollectionId, options?: { deleteNotes?: boolean }): Promise<void>;
}

const GroupsContext = createContext<GroupTree | null>(null);

export function useGroups(): GroupTree {
  const value = useContext(GroupsContext);
  if (value === null) {
    throw new Error('useGroups must be used inside <GroupsProvider>');
  }
  return value;
}

/**
 * The tree if there is one, `null` if this is rendered outside the provider.
 *
 * For code that would *like* to keep the tree honest but must not fall over without it — the note
 * actions, which are also used by screens that exist before the shell is mounted.
 */
export function useGroupsOptional(): GroupTree | null {
  return useContext(GroupsContext);
}

const CACHE_KEY = 'rosie-notes:groups';

function readCache(): Group[] | null {
  try {
    const raw = globalThis.localStorage?.getItem(CACHE_KEY);
    if (raw === null || raw === undefined) return null;
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as Group[]) : null;
  } catch {
    return null;
  }
}

function writeCache(groups: readonly Group[]): void {
  try {
    globalThis.localStorage?.setItem(CACHE_KEY, JSON.stringify(groups));
  } catch {
    // Over quota, or storage disabled. The next cold start simply waits for the network.
  }
}

/** The empty resolve: what a note in no group at all behaves by. */
const DEFAULT_RESOLVED: ResolvedGroupSettings = resolveGroupSettings([]);

export function GroupsProvider({ children }: { readonly children: ReactNode }): React.JSX.Element {
  const workspace = useWorkspace();
  const [groups, setGroups] = useState<readonly Group[]>(() => readCache() ?? []);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<NotesClientError | null>(null);
  const [stale, setStale] = useState(false);

  const reload = useCallback(async () => {
    setLoading(true);
    try {
      // No `parentId`: every group at every depth, which is what a breadcrumb needs.
      const page = await workspace.client.groups.list({ limit: 200 });
      setGroups(page.items);
      writeCache(page.items);
      setError(null);
      setStale(false);
    } catch (caught) {
      // The last known tree stays on screen. A cached tree is an answer, not a failure — only a
      // failure with nothing cached is worth an error state.
      const cached = readCache();
      if (cached !== null && cached.length > 0) {
        setGroups(cached);
        setStale(true);
        setError(null);
      } else if (isClientError(caught)) {
        setError(caught);
      }
    } finally {
      setLoading(false);
    }
  }, [workspace]);

  useEffect(() => {
    void reload();
  }, [reload]);

  const value = useMemo<GroupTree>(() => {
    const byId = new Map<string, Group>(groups.map((group) => [group.id as string, group]));

    const childrenOf = new Map<string | null, Group[]>();
    for (const group of groups) {
      const key = group.parentId === null ? null : (group.parentId as string);
      const bucket = childrenOf.get(key);
      if (bucket === undefined) childrenOf.set(key, [group]);
      else bucket.push(group);
    }
    for (const bucket of childrenOf.values()) {
      bucket.sort(
        (left, right) => left.position - right.position || left.name.localeCompare(right.name),
      );
    }

    function children(parentId: string | null): readonly Group[] {
      return childrenOf.get(parentId) ?? [];
    }

    function chain(groupId: string | null): readonly Group[] {
      const out: Group[] = [];
      let current = groupId === null ? undefined : byId.get(groupId);
      // A malformed tree — a parent that points at a descendant — would otherwise spin forever.
      const seen = new Set<string>();
      while (current !== undefined && !seen.has(current.id as string)) {
        seen.add(current.id as string);
        out.unshift(current);
        current = current.parentId === null ? undefined : byId.get(current.parentId as string);
      }
      return out;
    }

    function tally(groupId: string): { notes: number; groups: number } {
      let notes = byId.get(groupId)?.noteCount ?? 0;
      let count = 0;
      const stack = [...children(groupId)];
      while (stack.length > 0) {
        const next = stack.pop();
        if (next === undefined) continue;
        count += 1;
        notes += next.noteCount;
        stack.push(...children(next.id as string));
      }
      return { notes, groups: count };
    }

    function colourOf(groupId: string | null): AccentName | null {
      // Nearest first: a subgroup's own colour wins over its parent's, and a group with none
      // inherits the closest coloured ancestor before falling back to the app accent.
      for (const group of [...chain(groupId)].reverse()) {
        const accent = accentFromColour(group.colour);
        if (accent !== null) return accent;
      }
      return null;
    }

    function settingsOf(groupId: string | null): ResolvedGroupSettings {
      if (groupId === null) return DEFAULT_RESOLVED;
      const walked = chain(groupId);
      if (walked.length === 0) return DEFAULT_RESOLVED;
      return resolveGroupSettings(
        walked.map((group) => ({ id: group.id as string, settings: group.settings })),
      );
    }

    return {
      byId,
      roots: children(null),
      loading,
      error,
      stale,
      children,
      chain,
      tally,
      colourOf,
      settingsOf,
      reload,
      async create(input) {
        const created = await workspace.client.groups.create(input);
        setGroups((previous) => {
          const next = [...previous, created];
          writeCache(next);
          return next;
        });
        return created;
      },
      async update(id, patch) {
        const updated = await workspace.client.groups.update(id, patch);
        setGroups((previous) => {
          const next = previous.map((group) => (group.id === id ? updated : group));
          writeCache(next);
          return next;
        });
        return updated;
      },
      async remove(id, options = {}) {
        await workspace.client.groups.remove(id, { deleteNotes: options.deleteNotes ?? false });
        // The server promotes subgroups to the top level rather than destroying them, so the
        // local tree is rebuilt from the server rather than guessed at.
        await reload();
      },
    };
  }, [groups, loading, error, stale, reload, workspace]);

  return <GroupsContext.Provider value={value}>{children}</GroupsContext.Provider>;
}

/**
 * One group's settings, with the server's own view of where each value came from.
 *
 * The local resolve paints first — it is the same function the server runs, over a chain this
 * client already holds — and the server's answer replaces it when it arrives. That ordering is
 * what makes the settings screen open instantly and still be right when two devices disagree.
 */
export interface GroupSettingsState {
  readonly resolved: ResolvedGroupSettings;
  readonly effective: GroupSettings;
  readonly loading: boolean;
  /** Resolved locally rather than confirmed by the server. */
  readonly local: boolean;
  reload(): void;
}

export function useGroupSettings(groupId: string | null): GroupSettingsState {
  const workspace = useWorkspace();
  const tree = useGroups();
  const [fromServer, setFromServer] = useState<ResolvedGroupSettings | null>(null);
  const [loading, setLoading] = useState(false);
  const [nonce, setNonce] = useState(0);

  const localResolve = tree.settingsOf(groupId);

  // biome-ignore lint/correctness/useExhaustiveDependencies: nonce is a deliberate re-run trigger
  useEffect(() => {
    if (groupId === null) {
      setFromServer(null);
      return;
    }
    let cancelled = false;
    setLoading(true);
    void (async () => {
      try {
        const response = await workspace.client.groups.settings(groupId as CollectionId);
        if (!cancelled) setFromServer(response);
      } catch {
        // Offline. The local resolve is already on screen and is the same computation.
        if (!cancelled) setFromServer(null);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [groupId, workspace, nonce]);

  const resolved = fromServer ?? localResolve;

  return {
    resolved,
    effective: resolved.effective ?? DEFAULT_GROUP_SETTINGS,
    loading,
    local: fromServer === null,
    reload: useCallback(() => setNonce((value) => value + 1), []),
  };
}
