import type { PlatformAdapter } from '@rosie-notes/core';
import { useCallback, useEffect, useRef } from 'react';
import { useAppearance } from './hooks/use-appearance';
import { DEFAULT_ROUTE, isPublicRoute, parseRoute } from './routing/routes';
import { useCurrentHash, useNavigate, useRoute } from './routing/use-route';
import { SessionProvider, useSession } from './session/session-context';
import { AppShell } from './ui/app-shell';
import { IconSprite } from './ui/icons';
import { ShareView } from './ui/share-view';
import { AuthView } from './ui/sign-in';
import { LoadingState } from './ui/states';

/**
 * The root: session first, then a route.
 *
 * The guard is four lines and one ref, and both halves matter. Sending an unauthenticated visitor
 * to the sign-in form is the easy half; **putting them back where they were** is the half that is
 * usually missing, and it is the difference between a deep link into a group being useful and
 * being a round trip through the front door. The address they asked for is stashed as `next` on
 * the sign-in route, so it survives a reload of the sign-in page itself.
 *
 * The `[data-rn]` wrapper is applied by {@link AppShell} for the signed-in app, and here for the
 * two screens that exist before it — sign-in and the share page — so the palette is in scope
 * everywhere without ever being declared on `:root`.
 */

export interface AppProps {
  readonly adapter: PlatformAdapter;
  readonly baseUrl: string;
}

export function App({ adapter, baseUrl }: AppProps): React.JSX.Element {
  return (
    <SessionProvider adapter={adapter} baseUrl={baseUrl}>
      <Gate />
    </SessionProvider>
  );
}

function Gate(): React.JSX.Element {
  const { status, baseUrl } = useSession();
  const route = useRoute();
  const hash = useCurrentHash();
  const navigate = useNavigate();
  const appearance = useAppearance();

  // The address that was asked for before the redirect. A ref, not state: it must not cause a
  // render of its own, and it has to survive the navigation that replaces the route.
  const intended = useRef<string | null>(null);

  const publicRoute = isPublicRoute(route);
  const sharePage = route.name === 'share';

  useEffect(() => {
    if (status !== 'signedOut' || publicRoute) {
      return;
    }
    // Remember where they were going, unless they were going nowhere in particular.
    const wanted = hash === '' || hash === '#' ? null : hash;
    intended.current = wanted;
    navigate({ name: 'signIn', next: wanted }, { replace: true });
  }, [status, publicRoute, hash, navigate]);

  const onSignedIn = useCallback(() => {
    const target =
      route.name === 'signIn' || route.name === 'register' ? route.next : intended.current;
    intended.current = null;
    navigate(target === null || target === undefined ? DEFAULT_ROUTE : parseRoute(target), {
      replace: true,
    });
  }, [navigate, route]);

  // Someone who is already signed in and lands on the sign-in page belongs in the app. A share
  // link is the exception that proves it: following one while signed in should still show the
  // shared note, not silently dump you in your own library.
  useEffect(() => {
    if (
      status === 'signedIn' &&
      publicRoute &&
      route.name !== 'resetPassword' &&
      route.name !== 'share'
    ) {
      navigate(DEFAULT_ROUTE, { replace: true });
    }
  }, [status, publicRoute, route.name, navigate]);

  // Before the session is even considered: a shared note has to open for a visitor with no
  // account, and there is nothing about it that needs the workspace to have booted.
  if (sharePage && route.name === 'share') {
    return (
      <div
        data-accent={appearance.accent}
        data-density={appearance.density}
        data-hover={appearance.hover}
        data-rn=""
        data-theme={appearance.theme}
      >
        <IconSprite />
        <ShareView baseUrl={baseUrl} shareId={route.shareId} />
      </div>
    );
  }

  if (status === 'restoring') {
    return (
      <div
        data-accent={appearance.accent}
        data-density={appearance.density}
        data-hover={appearance.hover}
        data-rn=""
        data-theme={appearance.theme}
      >
        <main className="booting">
          <LoadingState label="Opening your notes…" />
        </main>
      </div>
    );
  }

  if (status === 'signedOut' || publicRoute) {
    return (
      <div
        data-accent={appearance.accent}
        data-density={appearance.density}
        data-hover={appearance.hover}
        data-rn=""
        data-theme={appearance.theme}
      >
        <IconSprite />
        <AuthView
          onNavigate={(next) => navigate(next, { replace: true })}
          onSignedIn={onSignedIn}
          route={publicRoute ? route : { name: 'signIn', next: intended.current }}
        />
      </div>
    );
  }

  return <AppShell appearance={appearance} route={route} theme={appearance.theme} />;
}
