import type {
  GroupSettingKey,
  GroupSettings,
  ResolvedGroupSettings,
  SettingOrigin,
} from '@rosie-notes/schema';
import type { ReactNode } from 'react';
import { InheritanceMark, OptionStrip, SetRow, SetSwitchRow } from './primitives';

/**
 * Setting rows that know where their value came from.
 *
 * Every row here takes the `origins` map from `resolveGroupSettings` and shows the answer to the
 * one question a cascade forces: **is this mine, or am I seeing somebody else's decision?** That
 * matters because it decides whether editing the parent will move this value. A settings screen
 * that shows fifteen values with no provenance is a screen you cannot safely change anything on.
 *
 * The marker is deliberately the same component for every family — sharing, notifications,
 * layout, code-project — because they are one interaction wearing three hats, and the moment they
 * diverge a person has three things to learn instead of one.
 */

export interface OriginProps {
  readonly origins: ResolvedGroupSettings['origins'];
  /** Group ids to names, so an origin can be shown as "from *Dreams*" rather than as a UUID. */
  readonly nameOf: (groupId: string | null) => string | null;
  /** The group being edited, so "set by me" is distinguishable from "set by an ancestor". */
  readonly groupId: string | null;
}

function originFor(
  props: OriginProps,
  key: GroupSettingKey,
): { source: SettingOrigin['source']; from: string | null } {
  const origin = props.origins[key];
  if (origin === undefined) return { source: 'default', from: null };
  return { source: origin.source, from: props.nameOf(origin.setBy) };
}

/** The pill: "Set here", "from *Dreams*", or "Default". */
export function OriginMark({
  origin,
  settingKey,
}: {
  readonly origin: OriginProps;
  readonly settingKey: GroupSettingKey;
}): React.JSX.Element {
  const resolved = originFor(origin, settingKey);
  return <InheritanceMark from={resolved.from} source={resolved.source} />;
}

export interface ChoiceRowProps<T extends string> {
  readonly label: string;
  readonly help?: ReactNode;
  readonly options: readonly { readonly value: T; readonly label: string }[];
  readonly value: T;
  readonly onChange: (next: T) => void;
  readonly expanded: boolean;
  readonly onToggle: () => void;
  readonly origin: OriginProps;
  readonly settingKey: GroupSettingKey;
}

/**
 * Label and help on the left, the value **as a word** on the right, chevron.
 *
 * Tapping expands an inline option strip. Never a modal, and never a native `<select>` — a
 * `<select>` on a phone hands the whole decision to an OS widget that cannot show which option is
 * inherited, which is the one thing this screen exists to communicate.
 */
export function ChoiceRow<T extends string>({
  label,
  help,
  options,
  value,
  onChange,
  expanded,
  onToggle,
  origin,
  settingKey,
}: ChoiceRowProps<T>): React.JSX.Element {
  const current = options.find((option) => option.value === value);
  return (
    <SetRow
      expanded={expanded}
      help={help}
      label={label}
      onClick={onToggle}
      value={
        <>
          <OriginMark origin={origin} settingKey={settingKey} />
          <span>{current?.label ?? '—'}</span>
        </>
      }
    >
      <OptionStrip label={label} onChange={onChange} options={options} value={value} />
    </SetRow>
  );
}

export interface SwitchRowProps {
  readonly label: string;
  readonly help?: ReactNode;
  readonly value: boolean;
  readonly onChange: (next: boolean) => void;
  readonly origin: OriginProps;
  readonly settingKey: GroupSettingKey;
}

export function SwitchRow({
  label,
  help,
  value,
  onChange,
  origin,
  settingKey,
}: SwitchRowProps): React.JSX.Element {
  return (
    <SetSwitchRow
      checked={value}
      help={help}
      label={label}
      mark={<OriginMark origin={origin} settingKey={settingKey} />}
      onChange={onChange}
    />
  );
}

/** Every settings key, so a screen can iterate rather than repeat itself. */
export type SettingsPatch = Partial<{
  [K in keyof GroupSettings]: GroupSettings[K] | null;
}>;
