import { isSessionExpiredError } from '@rosie-notes/client';
import type { PlatformAdapter } from '@rosie-notes/core';
import type { User } from '@rosie-notes/schema';
import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { createWorkspace, type Workspace } from './workspace';

/**
 * The session, as React sees it.
 *
 * The workspace — client, sync engine, store, write queue — is built once and lives in a ref. It
 * is *not* state: rebuilding it on a re-render would drop the sync engine's in-flight work and
 * reopen every Yjs document, and it never changes identity while the app is running.
 *
 * What is state is the small amount the UI actually branches on: are we still working out
 * whether there is a session, is there one, and who is it.
 */

export type SessionStatus = 'restoring' | 'signedOut' | 'signedIn';

export interface RegisterInput {
  readonly username: string;
  readonly email: string;
  readonly password: string;
  readonly displayName?: string | undefined;
}

export interface SessionValue {
  readonly status: SessionStatus;
  readonly user: User | null;
  readonly workspace: Workspace | null;
  readonly baseUrl: string;
  /** Set when the workspace itself could not be built — a bad base URL, storage unavailable. */
  readonly startupError: Error | null;
  signIn(identifier: string, password: string): Promise<void>;
  register(input: RegisterInput): Promise<void>;
  signOut(options?: { forget?: boolean }): Promise<void>;
  changePassword(input: {
    currentPassword: string;
    newPassword: string;
    signOutOtherSessions?: boolean;
  }): Promise<number>;
  requestPasswordReset(email: string): Promise<void>;
  confirmPasswordReset(token: string, newPassword: string): Promise<void>;
}

const SessionContext = createContext<SessionValue | null>(null);

export function useSession(): SessionValue {
  const value = useContext(SessionContext);
  if (value === null) {
    throw new Error('useSession must be used inside <SessionProvider>');
  }
  return value;
}

/** The workspace, for the many components that need the store and nothing else. */
export function useWorkspace(): Workspace {
  const { workspace } = useSession();
  if (workspace === null) {
    throw new Error('useWorkspace must be used inside a signed-in tree');
  }
  return workspace;
}

export interface SessionProviderProps {
  readonly adapter: PlatformAdapter;
  readonly baseUrl: string;
  readonly children: ReactNode;
}

export function SessionProvider({
  adapter,
  baseUrl,
  children,
}: SessionProviderProps): React.JSX.Element {
  const workspaceRef = useRef<Workspace | null>(null);
  const [workspace, setWorkspace] = useState<Workspace | null>(null);
  const [status, setStatus] = useState<SessionStatus>('restoring');
  const [user, setUser] = useState<User | null>(null);
  const [startupError, setStartupError] = useState<Error | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function boot(): Promise<void> {
      try {
        const built = await createWorkspace({
          adapter,
          baseUrl,
          onAuthStateChange: (signedIn) => {
            // A refresh that failed while the tab was in the background lands here, which is the
            // only warning the UI gets that the session is gone.
            if (!signedIn) {
              setStatus('signedOut');
              setUser(null);
            }
          },
        });
        if (cancelled) {
          built.dispose();
          return;
        }
        workspaceRef.current = built;
        setWorkspace(built);

        if (!(await built.client.isSignedIn())) {
          setStatus('signedOut');
          return;
        }

        // There are tokens; whether the server still honours them is another question. Asking
        // now means the app either opens signed in or shows the sign-in form, never a shell that
        // fails on its first request.
        try {
          const session = await built.client.auth.session();
          if (cancelled) return;
          built.store.setOwnerId(session.user.id);
          setUser(session.user);
          setStatus('signedIn');
        } catch (error) {
          if (cancelled) return;
          if (isSessionExpiredError(error)) {
            setStatus('signedOut');
            return;
          }
          // Offline with tokens in hand: open the app anyway. The cache has notes in it and the
          // sync engine will catch up; refusing to start would make the app useless on a train.
          setStatus('signedIn');
        }
      } catch (error) {
        if (cancelled) return;
        setStartupError(error instanceof Error ? error : new Error(String(error)));
        setStatus('signedOut');
      }
    }

    void boot();
    return () => {
      cancelled = true;
      workspaceRef.current?.dispose();
      workspaceRef.current = null;
    };
  }, [adapter, baseUrl]);

  const requireWorkspace = useCallback((): Workspace => {
    const built = workspaceRef.current;
    if (built === null) {
      throw new Error('The app has not finished starting');
    }
    return built;
  }, []);

  const afterSignIn = useCallback((signedInUser: User, built: Workspace) => {
    built.store.setOwnerId(signedInUser.id);
    setUser(signedInUser);
    setStatus('signedIn');
  }, []);

  const signIn = useCallback(
    async (identifier: string, password: string) => {
      const built = requireWorkspace();
      const response = await built.client.auth.login({ identifier, password });
      afterSignIn(response.user, built);
    },
    [afterSignIn, requireWorkspace],
  );

  const register = useCallback(
    async (input: RegisterInput) => {
      const built = requireWorkspace();
      const response = await built.client.auth.register({
        username: input.username,
        email: input.email,
        password: input.password,
        ...(input.displayName === undefined || input.displayName === ''
          ? {}
          : { displayName: input.displayName }),
      });
      afterSignIn(response.user, built);
    },
    [afterSignIn, requireWorkspace],
  );

  const signOut = useCallback(async (options: { forget?: boolean } = {}) => {
    const built = workspaceRef.current;
    setStatus('signedOut');
    setUser(null);
    if (built === null) return;
    try {
      await built.client.auth.logout();
    } catch {
      // The tokens are cleared locally either way; a failed logout call is not worth a dialog.
    }
    if (options.forget === true) {
      await built.writes.clear();
      await built.adapter.cache.clear();
    }
  }, []);

  const changePassword = useCallback(
    async (input: {
      currentPassword: string;
      newPassword: string;
      signOutOtherSessions?: boolean;
    }) => {
      const result = await requireWorkspace().client.auth.changePassword({
        currentPassword: input.currentPassword,
        newPassword: input.newPassword,
        signOutOtherSessions: input.signOutOtherSessions ?? true,
      });
      return result.revokedSessions;
    },
    [requireWorkspace],
  );

  const requestPasswordReset = useCallback(
    async (email: string) => {
      await requireWorkspace().client.auth.requestPasswordReset({ email });
    },
    [requireWorkspace],
  );

  const confirmPasswordReset = useCallback(
    async (token: string, newPassword: string) => {
      await requireWorkspace().client.auth.confirmPasswordReset({ token, newPassword });
      // Confirming revokes every session, this one included.
      setStatus('signedOut');
      setUser(null);
    },
    [requireWorkspace],
  );

  const value = useMemo<SessionValue>(
    () => ({
      status,
      user,
      workspace,
      baseUrl,
      startupError,
      signIn,
      register,
      signOut,
      changePassword,
      requestPasswordReset,
      confirmPasswordReset,
    }),
    [
      status,
      user,
      workspace,
      baseUrl,
      startupError,
      signIn,
      register,
      signOut,
      changePassword,
      requestPasswordReset,
      confirmPasswordReset,
    ],
  );

  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}
