import type { CollectionId, Note, NoteId } from '@rosie-notes/schema';
import { useCallback } from 'react';
import { useWorkspace } from '../session/session-context';
import { numberedTitle, renderAutoTitle } from '../ui/labels';
import { useGroups } from './use-groups';
import { useNoteActions } from './use-note-actions';

/**
 * "Add a note here" — one implementation, for the two buttons that mean it.
 *
 * The group page and the add sheet were doing this separately, which is how one of them ended up
 * with the automatic title and neither of them with the numbering the settings screen promises.
 * Everything a new note inherits from its group — its kind, its title rule — is decided here.
 */

/** Titles already in the group, for {@link numberedTitle}. Server first, cache when offline. */
async function titlesIn(
  list: () => Promise<readonly Note[]>,
  cached: () => Promise<readonly Note[]>,
  groupId: string,
): Promise<string[]> {
  let notes: readonly Note[];
  try {
    notes = await list();
  } catch {
    // Offline. Numbering off this device's copy is better than handing out a duplicate title,
    // and the worst case is a `(2)` that a second device also chose — a cosmetic clash, not a
    // lost note.
    notes = (await cached()).filter((note) => note.collectionIds.includes(groupId as CollectionId));
  }
  return notes.map((note) => note.title).filter((title) => title !== '');
}

export function useAddNote(): (groupId: string | null) => Promise<NoteId> {
  const workspace = useWorkspace();
  const tree = useGroups();
  const actions = useNoteActions();

  return useCallback(
    async (groupId) => {
      const settings = tree.settingsOf(groupId).effective;
      const group = groupId === null ? undefined : tree.byId.get(groupId);

      let title = '';
      if (settings.autoTitle.enabled) {
        title = renderAutoTitle(settings.autoTitle.template, group?.name ?? '');
        if (settings.autoTitle.numberWhenRepeated && groupId !== null) {
          const taken = await titlesIn(
            async () =>
              (
                await workspace.client.notes.list({
                  collectionId: groupId as CollectionId,
                  limit: 200,
                })
              ).items,
            () => workspace.adapter.cache.listNotes(),
            groupId,
          );
          title = numberedTitle(title, taken);
        }
      }

      return actions.create({
        title,
        kind: settings.newNoteKind,
        ...(groupId === null ? {} : { collectionIds: [groupId as CollectionId] }),
      });
    },
    [workspace, tree, actions],
  );
}
