import { createContext, useContext } from 'react';
import type { Appearance } from '../hooks/use-appearance';

/**
 * The few things a screen needs from the shell around it.
 *
 * Navigation is not here — that is `useNavigate`, and a screen that wants to go somewhere builds
 * a route value like everything else. What *is* here is the two things only the shell can own:
 * the layer stack (a sheet is a history entry, so only one place may push one) and the appearance
 * axes, which are painted onto the shell's own wrapper element.
 */

export interface ShellControl {
  /** Open the add sheet for a group, or for the top level with `null`. */
  openAdd(groupId: string | null): void;
  /** Open the "move this note" picker. */
  openMove(noteId: string): void;
  readonly appearance: Appearance;
}

const ShellContext = createContext<ShellControl | null>(null);

export const ShellProvider = ShellContext.Provider;

export function useShell(): ShellControl {
  const value = useContext(ShellContext);
  if (value === null) {
    throw new Error('useShell must be used inside the app shell');
  }
  return value;
}
