import { useCallback, useSyncExternalStore } from 'react';
import { parseRoute, type Route, routeToHash } from './routes';

/**
 * The current route, and a way to change it.
 *
 * `useSyncExternalStore` rather than `useState` + an effect: the hash is external state that can
 * change without React's involvement (the back button, a typed URL), and the store form is the
 * one that cannot tear during a concurrent render.
 */

function subscribe(onChange: () => void): () => void {
  globalThis.addEventListener('hashchange', onChange);
  return () => globalThis.removeEventListener('hashchange', onChange);
}

function currentHash(): string {
  return globalThis.location?.hash ?? '';
}

export function useRoute(): Route {
  // The snapshot is the hash string, not the parsed object: `useSyncExternalStore` compares
  // snapshots with `Object.is`, and parsing on every check would return a new object each time
  // and re-render forever.
  const hash = useSyncExternalStore(subscribe, currentHash, () => '');
  return parseRoute(hash);
}

/** The hash exactly as it stands — what the route guard stashes as `next`. */
export function useCurrentHash(): string {
  return useSyncExternalStore(subscribe, currentHash, () => '');
}

export type Navigate = (route: Route, options?: { replace?: boolean }) => void;

export function useNavigate(): Navigate {
  return useCallback((route: Route, options: { replace?: boolean } = {}) => {
    const hash = routeToHash(route);
    if (options.replace === true) {
      const { pathname, search } = globalThis.location;
      globalThis.history.replaceState(null, '', `${pathname}${search}${hash}`);
      globalThis.dispatchEvent(new HashChangeEvent('hashchange'));
      return;
    }
    if (globalThis.location.hash === hash) {
      // Assigning the same hash fires no `hashchange`, and a "go there" that does nothing is a
      // dead button. Re-dispatch so subscribers still settle on the right route.
      globalThis.dispatchEvent(new HashChangeEvent('hashchange'));
      return;
    }
    globalThis.location.hash = hash;
  }, []);
}
