import {
  type FetchLike,
  NotesClient,
  type StoredTokens,
  type TokenStorage,
} from '@rosie-notes/client';
import { NotesStore, type PlatformAdapter, SyncEngine } from '@rosie-notes/core';
import { type DeviceId, newId } from '@rosie-notes/schema';
import { type QueuedWrite, WriteQueue } from '../offline/write-queue';

/**
 * One assembled workspace: client, sync engine and store, wired together.
 *
 * Built once per signed-in session and thrown away on sign-out. Keeping the assembly in a plain
 * function rather than in a React component means the same three lines build the Android app's
 * workspace and the VSCode extension's — React is a rendering choice, not part of the shape of
 * the application.
 */

const DEVICE_ID_KEY = 'device-id';
const TOKENS_KEY = 'session-tokens';

/**
 * A device id that survives a reload.
 *
 * The server records which device an update came from, so a browser that mints a fresh id on
 * every load would look like an unbounded fleet of devices to anyone reading their own sync log.
 */
export async function resolveDeviceId(adapter: PlatformAdapter): Promise<DeviceId> {
  const existing = await adapter.storage.get(DEVICE_ID_KEY);
  if (existing !== null && existing !== '') {
    return existing as DeviceId;
  }
  const minted = newId<'device'>(adapter.clock());
  await adapter.storage.set(DEVICE_ID_KEY, minted);
  return minted;
}

/**
 * Tokens in the adapter's key-value store — `localStorage` on the web.
 *
 * Worth being straight about the trade-off: this is readable by any script that runs on the
 * origin, so it is not proof against XSS. The alternative, an httpOnly cookie, needs the API and
 * the app to share a site and brings CSRF back with it, and this app is deployed to a path on a
 * static host talking to an API on another hostname. `docs/security.md` says the same thing.
 */
export class AdapterTokenStorage implements TokenStorage {
  readonly #adapter: PlatformAdapter;

  constructor(adapter: PlatformAdapter) {
    this.#adapter = adapter;
  }

  async get(): Promise<StoredTokens | null> {
    const raw = await this.#adapter.storage.get(TOKENS_KEY);
    if (raw === null) {
      return null;
    }
    try {
      return JSON.parse(raw) as StoredTokens;
    } catch {
      // A corrupt entry is a sign-in prompt, not a crash.
      await this.#adapter.storage.remove(TOKENS_KEY);
      return null;
    }
  }

  async set(tokens: StoredTokens): Promise<void> {
    await this.#adapter.storage.set(TOKENS_KEY, JSON.stringify(tokens));
  }

  async clear(): Promise<void> {
    await this.#adapter.storage.remove(TOKENS_KEY);
  }
}

export interface Workspace {
  readonly client: NotesClient;
  readonly engine: SyncEngine;
  readonly store: NotesStore;
  readonly adapter: PlatformAdapter;
  readonly deviceId: DeviceId;
  /** Metadata writes that could not be delivered. Bodies ride the sync engine's own outbox. */
  readonly writes: WriteQueue;
  /** Push everything queued — the outbox and the write queue — and pull what is open. */
  flush(): Promise<void>;
  /** Stop syncing and release listeners. Does not clear the cache — sign-out does that. */
  dispose(): void;
}

export interface CreateWorkspaceOptions {
  readonly adapter: PlatformAdapter;
  readonly baseUrl: string;
  /** Called whenever the session is gained or lost, including a silent refresh failing. */
  readonly onAuthStateChange?: (signedIn: boolean) => void;
  /** A queued write the server refused on replay. Surfaced to the UI as a notice. */
  readonly onWriteDropped?: ((write: QueuedWrite, error: unknown) => void) | undefined;
}

export async function createWorkspace(options: CreateWorkspaceOptions): Promise<Workspace> {
  const { adapter, baseUrl } = options;
  const deviceId = await resolveDeviceId(adapter);

  const client = new NotesClient({
    baseUrl,
    fetch: adapter.net.fetch as FetchLike,
    storage: new AdapterTokenStorage(adapter),
    onAuthStateChange: (change) => options.onAuthStateChange?.(change.tokens !== null),
    headers: { 'x-rosie-notes-client': 'web' },
  });

  const engine = new SyncEngine({ client, adapter, deviceId });
  await engine.start();

  const store = new NotesStore({ client, adapter, sync: engine });

  const writes = new WriteQueue({
    storage: adapter.storage,
    clock: () => adapter.clock(),
    random: () => adapter.random(),
    ...(options.onWriteDropped === undefined ? {} : { onDropped: options.onWriteDropped }),
    // The queue performs its writes through the store, not the client, so a replay updates the
    // cache and every subscriber exactly as the original attempt did.
    apply: async (write) => {
      switch (write.kind) {
        case 'create':
          await store.createNote({ ...write.input, id: write.noteId });
          return;
        case 'update':
          await store.updateNote(write.noteId, write.patch);
          return;
        case 'trash':
          await store.deleteNote(write.noteId);
          return;
        case 'purge':
          await store.deleteNote(write.noteId, { permanent: true });
          return;
        default:
          await client.notes.restore(write.noteId);
          await store.loadNote(write.noteId);
      }
    },
  });
  await writes.load();

  return {
    client,
    engine,
    store,
    adapter,
    deviceId,
    writes,
    async flush() {
      await writes.flush();
      await engine.flush();
    },
    dispose() {
      engine.stop();
    },
  };
}
