/**
 * Turning the server's highlighted snippet into text, safely.
 *
 * `SearchHighlight.snippet` arrives as a string containing `<mark>` around the matched terms with
 * everything else HTML-escaped. The obvious thing to do with it is `dangerouslySetInnerHTML`, and
 * that is exactly what this module exists to avoid: **no user-supplied text is ever rendered as
 * markup in this app**, and a search result is user-supplied text by definition — it is somebody's
 * note body coming back through a query.
 *
 * So the snippet is parsed instead. `<mark>` is recognised as a *structural* token from a known
 * producer, everything between the tags is unescaped back into plain characters, and the caller
 * renders the segments as React nodes — where React escapes them again on the way out. A note
 * containing a script tag comes back through search as the visible characters of a script tag.
 *
 * If the server ever emits a tag this does not know about, it is left as literal text rather than
 * interpreted. Being conservative here fails as visible noise, which is the failure you want.
 */

export interface Segment {
  readonly text: string;
  readonly marked: boolean;
}

const ENTITIES: Readonly<Record<string, string>> = {
  '&amp;': '&',
  '&lt;': '<',
  '&gt;': '>',
  '&quot;': '"',
  '&#39;': "'",
  '&#x27;': "'",
  '&nbsp;': ' ',
};

/** Reverse the server's escaping. Numeric forms are handled for the two the API actually emits. */
export function unescapeHtml(value: string): string {
  return value.replace(
    /&(?:amp|lt|gt|quot|nbsp|#39|#x27);/g,
    (entity) => ENTITIES[entity] ?? entity,
  );
}

/**
 * Split a snippet into plain and marked runs.
 *
 * Unbalanced or unexpected tags degrade to text rather than throwing: a search result is not
 * worth an error boundary, and a stray `<mark` shown literally is a far better outcome than a
 * blank result row.
 */
export function parseHighlight(snippet: string): readonly Segment[] {
  const segments: Segment[] = [];
  const pattern = /<mark>([\s\S]*?)<\/mark>/g;
  let cursor = 0;

  for (let match = pattern.exec(snippet); match !== null; match = pattern.exec(snippet)) {
    if (match.index > cursor) {
      segments.push({ text: unescapeHtml(snippet.slice(cursor, match.index)), marked: false });
    }
    segments.push({ text: unescapeHtml(match[1] ?? ''), marked: true });
    cursor = match.index + match[0].length;
  }

  if (cursor < snippet.length) {
    segments.push({ text: unescapeHtml(snippet.slice(cursor)), marked: false });
  }

  return segments.filter((segment) => segment.text !== '');
}

/** The snippet with its marks removed — for a `title` attribute or a plain-text excerpt. */
export function highlightToText(snippet: string): string {
  return parseHighlight(snippet)
    .map((segment) => segment.text)
    .join('');
}
