import { isApiError, NotesClient } from '@rosie-notes/client';
import type { NoteDetail, PublicShare } from '@rosie-notes/schema';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { shortWhen } from './labels';
import { EmptyState, LoadingState } from './states';

/**
 * A shared note, read-only, for somebody who may not have an account here.
 *
 * ## Why this builds its own client
 *
 * It does not use the workspace. The workspace is a signed-in thing — a store, a sync engine, a
 * write queue, an IndexedDB cache — and none of it applies to a page whose entire job is to show
 * one note to a stranger and write nothing anywhere. A bare {@link NotesClient} with the default
 * in-memory token storage keeps a share page from touching the visitor's disk at all.
 *
 * ## Why the body is rendered as text
 *
 * The note arrives as markdown the *owner* wrote, and this page is shown to whoever holds the
 * link. Handing that to an HTML renderer would make a note into a script delivery mechanism aimed
 * at everybody it is shared with, so it is rendered in a `<pre>` — the source, verbatim, with no
 * interpretation. Rich rendering here needs a sanitiser, and a sanitiser needs a decision that is
 * not this component's to make.
 *
 * ## What it refuses to say
 *
 * A share that was revoked and a share id that was never real both arrive as `share.not_found`,
 * and this page treats them identically — a distinct "this was revoked" message would undo the
 * server's work of making the two indistinguishable.
 */

export interface ShareViewProps {
  readonly shareId: string;
  readonly baseUrl: string;
}

type Status =
  | { readonly state: 'loading' }
  | { readonly state: 'locked'; readonly wrong: boolean }
  | { readonly state: 'ready'; readonly share: PublicShare; readonly note: NoteDetail }
  | { readonly state: 'gone'; readonly title: string; readonly body: string };

const GONE: Record<string, { title: string; body: string }> = {
  'share.not_found': {
    title: 'This link does not work',
    body: 'It may have been revoked, or the address may be incomplete. Ask whoever sent it for a fresh one.',
  },
  'share.expired': {
    title: 'This link has expired',
    body: 'The person who shared it set an end date, and it has passed.',
  },
  'share.view_limit_reached': {
    title: 'This link has been used up',
    body: 'It was set to work a limited number of times, and it has reached that limit.',
  },
  'rate_limit.exceeded': {
    title: 'Too many attempts',
    body: 'Wait a minute or two and try again.',
  },
};

const UNREACHABLE = {
  title: 'Could not reach the server',
  body: 'Check your connection and reload the page.',
};

export function ShareView({ shareId, baseUrl }: ShareViewProps): React.JSX.Element {
  const client = useMemo(() => new NotesClient({ baseUrl }), [baseUrl]);
  const [status, setStatus] = useState<Status>({ state: 'loading' });
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);

  const open = useCallback(
    async (secret: string | undefined): Promise<void> => {
      try {
        const resolved = await client.shares.resolve({
          token: shareId,
          ...(secret === undefined || secret === '' ? {} : { password: secret }),
        });
        setStatus({ state: 'ready', share: resolved.share, note: resolved.note });
      } catch (error) {
        if (!isApiError(error)) {
          setStatus({ state: 'gone', ...UNREACHABLE });
          return;
        }
        if (error.is('share.password_required')) {
          setStatus({ state: 'locked', wrong: false });
          return;
        }
        if (error.is('share.password_invalid')) {
          setStatus({ state: 'locked', wrong: true });
          return;
        }
        setStatus({
          state: 'gone',
          ...(GONE[error.code] ?? GONE['share.not_found'] ?? UNREACHABLE),
        });
      }
    },
    [client, shareId],
  );

  useEffect(() => {
    setStatus({ state: 'loading' });
    void open(undefined);
  }, [open]);

  async function unlock(event: React.FormEvent): Promise<void> {
    event.preventDefault();
    setBusy(true);
    await open(password);
    setBusy(false);
  }

  if (status.state === 'loading') {
    return (
      <main className="booting">
        <LoadingState label="Opening the shared note…" />
      </main>
    );
  }

  if (status.state === 'gone') {
    return (
      <main className="auth">
        <div className="auth__card">
          <EmptyState body={status.body} title={status.title} />
        </div>
      </main>
    );
  }

  if (status.state === 'locked') {
    return (
      <main className="auth">
        <div className="auth__card">
          <h1 className="auth__title">This note needs a password</h1>
          <form className="form" onSubmit={(event) => void unlock(event)}>
            <label className="field">
              <span className="field__label">Password</span>
              {/* No `autoFocus`: it steals a screen reader's place on the page before it has
                  read the heading explaining why a password is being asked for at all. */}
              <input
                autoComplete="off"
                className="field__input"
                onChange={(event) => setPassword(event.target.value)}
                required
                type="password"
                value={password}
              />
            </label>
            {status.wrong && (
              <p className="auth__error" role="alert">
                That password is not right.
              </p>
            )}
            <div className="form__actions">
              <button className="button button--primary" disabled={busy} type="submit">
                {busy ? 'Checking…' : 'Unlock'}
              </button>
            </div>
          </form>
          <p className="auth__footnote">
            Whoever shared this note chose the password; this server cannot look it up.
          </p>
        </div>
      </main>
    );
  }

  const { share, note } = status;
  return (
    <main className="share-view">
      <article className="share-view__card">
        <header className="share-view__header">
          <h1 className="share-view__title">{note.title === '' ? 'Untitled' : note.title}</h1>
          <p className="share-view__meta">
            Shared by {share.owner.displayName} · updated {shortWhen(note.updatedAt)}
            {share.expiresAt === null ? '' : ` · expires ${shortWhen(share.expiresAt)}`}
          </p>
          {note.tags.length > 0 && (
            <ul className="share-view__tags">
              {note.tags.map((tag) => (
                <li className="chip chip--tag" key={tag}>
                  #{tag}
                </li>
              ))}
            </ul>
          )}
        </header>
        {/* Verbatim, not rendered. See the note at the top of this file. */}
        <pre className="share-view__body">{note.body?.text ?? ''}</pre>
        <footer className="share-view__footer">
          <p className="settings__hint">
            You are reading a shared copy. Nothing you do here changes the original.
          </p>
        </footer>
      </article>
    </main>
  );
}
