import { isClientError } from '@rosie-notes/client';
import type { KeyValueStore, Unsubscribe } from '@rosie-notes/core';
import type { NoteCreateRequestInput, NoteId, NoteUpdateRequest } from '@rosie-notes/schema';

/**
 * The offline queue for *metadata* writes.
 *
 * `@rosie-notes/core` already carries note **bodies** across a disconnection: every keystroke
 * becomes a Yjs update in the sync engine's outbox, on disk, and is pushed when the server comes
 * back. What it does not carry is the REST half — renaming a note, pinning it, changing its kind,
 * adding a tag, trashing it. Those are ordinary `PATCH`es, and without something like this one
 * made on a train is applied locally, fails, and is silently never sent.
 *
 * So this is the same idea, one layer up, and it borrows the outbox's three rules verbatim:
 *
 * - **Nothing is lost.** A write that could not be delivered is on disk before `submit` resolves.
 * - **Order is preserved.** Entries replay oldest-first, so "rename, then trash" cannot arrive
 *   the other way round.
 * - **Offline is not rejection.** Only a failure the *server* returned discards a write; a
 *   request that never landed is queued and retried. `NotesStore` draws the same line, which is
 *   why the optimistic local state and this queue always agree about what happened.
 *
 * Consecutive patches to one note are merged, so holding down a key in the title field while
 * offline leaves one entry rather than forty.
 */

export const WRITE_QUEUE_STORAGE_KEY = 'writes:notes';

export type QueuedWrite =
  | {
      readonly kind: 'create';
      readonly id: string;
      readonly at: number;
      readonly noteId: NoteId;
      readonly input: NoteCreateRequestInput;
    }
  | {
      readonly kind: 'update';
      readonly id: string;
      readonly at: number;
      readonly noteId: NoteId;
      readonly patch: NoteUpdateRequest;
    }
  | {
      readonly kind: 'trash';
      readonly id: string;
      readonly at: number;
      readonly noteId: NoteId;
    }
  | {
      readonly kind: 'purge';
      readonly id: string;
      readonly at: number;
      readonly noteId: NoteId;
    }
  | {
      readonly kind: 'restore';
      readonly id: string;
      readonly at: number;
      readonly noteId: NoteId;
    };

/** A write as the caller describes it: no id and no timestamp, because those are ours to mint. */
export type WriteRequest =
  | { readonly kind: 'create'; readonly noteId: NoteId; readonly input: NoteCreateRequestInput }
  | { readonly kind: 'update'; readonly noteId: NoteId; readonly patch: NoteUpdateRequest }
  | { readonly kind: 'trash'; readonly noteId: NoteId }
  | { readonly kind: 'purge'; readonly noteId: NoteId }
  | { readonly kind: 'restore'; readonly noteId: NoteId };

/** What actually performs a write. Injected, so the queue never knows about the store. */
export type WriteApplier = (write: QueuedWrite) => Promise<void>;

export type WriteOutcome = 'applied' | 'queued';

export interface FlushSummary {
  readonly flushed: number;
  readonly remaining: number;
  readonly outcome: 'done' | 'offline' | 'empty';
}

export interface WriteQueueOptions {
  readonly storage: KeyValueStore;
  readonly apply: WriteApplier;
  readonly clock: () => number;
  readonly random: () => string;
  readonly key?: string | undefined;
  /** A write the server refused during a replay. There is no UI left to throw it at. */
  readonly onDropped?: ((write: QueuedWrite, error: unknown) => void) | undefined;
}

/**
 * Did this fail because the server said no, or because it never heard the question?
 *
 * Only the first is a reason to give up on a write. `NotesStore` uses exactly this distinction to
 * decide whether to roll an optimistic change back, so the two stay in step by construction.
 */
export function isDeliveryFailure(error: unknown): boolean {
  if (!isClientError(error)) {
    // A `TypeError: Failed to fetch` from a `fetch` that never got wrapped still means offline.
    return error instanceof TypeError;
  }
  return error.kind === 'network' || error.kind === 'timeout';
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

/** A corrupt queue is dropped rather than crashing the app on launch. */
function parseEntries(raw: string): QueuedWrite[] {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) {
      return [];
    }
    return parsed.filter((entry): entry is QueuedWrite => {
      if (!isRecord(entry)) {
        return false;
      }
      return (
        typeof entry['id'] === 'string' &&
        typeof entry['noteId'] === 'string' &&
        typeof entry['at'] === 'number' &&
        typeof entry['kind'] === 'string'
      );
    });
  } catch {
    return [];
  }
}

export class WriteQueue {
  readonly #options: WriteQueueOptions;
  readonly #key: string;
  readonly #listeners = new Set<(entries: readonly QueuedWrite[]) => void>();

  #entries: QueuedWrite[] = [];
  #loaded = false;
  /** Serialises flushes. Never rejects, so one failed flush cannot poison the next. */
  #chain: Promise<unknown> = Promise.resolve();

  constructor(options: WriteQueueOptions) {
    this.#options = options;
    this.#key = options.key ?? WRITE_QUEUE_STORAGE_KEY;
  }

  get size(): number {
    return this.#entries.length;
  }

  get entries(): readonly QueuedWrite[] {
    return this.#entries;
  }

  get loaded(): boolean {
    return this.#loaded;
  }

  /** Read the queue back from storage. Call once on start; safe to call again. */
  async load(): Promise<void> {
    const raw = await this.#options.storage.get(this.#key);
    this.#entries = raw === null ? [] : parseEntries(raw);
    this.#loaded = true;
    this.#emit();
  }

  subscribe(listener: (entries: readonly QueuedWrite[]) => void): Unsubscribe {
    this.#listeners.add(listener);
    listener(this.#entries);
    return () => {
      this.#listeners.delete(listener);
    };
  }

  /**
   * Do the write now if the server is reachable, and queue it if not.
   *
   * Throws when the server *refused* — the caller has a form to put the message next to, and the
   * store has already rolled its optimistic change back.
   */
  async submit(request: WriteRequest): Promise<WriteOutcome> {
    const write = this.#materialise(request);
    if (!this.#loaded) {
      await this.load();
    }

    // Anything already queued has to go first, or a rename made offline would land after the
    // rename made online and win. Draining is the caller's job — `AppShell` flushes on reconnect,
    // on a retry timer while anything is waiting, and on demand from the sync badge.
    if (this.#entries.length > 0) {
      await this.#enqueue(write);
      return 'queued';
    }

    try {
      await this.#options.apply(write);
      return 'applied';
    } catch (error) {
      if (!isDeliveryFailure(error)) {
        throw error;
      }
      await this.#enqueue(write);
      return 'queued';
    }
  }

  /**
   * Send everything queued, oldest first.
   *
   * Flushes are serialised rather than shared. Sharing looks equivalent and is not: a caller that
   * asks *after* the network came back would be handed the answer of a flush that started while
   * it was still down, and would conclude — wrongly — that the queue is stuck.
   */
  async flush(): Promise<FlushSummary> {
    const run = this.#chain.then(
      () => this.#runFlush(),
      () => this.#runFlush(),
    );
    this.#chain = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }

  async clear(): Promise<void> {
    this.#entries = [];
    await this.#options.storage.remove(this.#key);
    this.#emit();
  }

  async #runFlush(): Promise<FlushSummary> {
    if (!this.#loaded) {
      await this.load();
    }
    if (this.#entries.length === 0) {
      return { flushed: 0, remaining: 0, outcome: 'empty' };
    }

    let flushed = 0;
    while (this.#entries.length > 0) {
      const entry = this.#entries[0];
      if (entry === undefined) {
        break;
      }
      try {
        await this.#options.apply(entry);
        flushed += 1;
      } catch (error) {
        if (isDeliveryFailure(error)) {
          return { flushed, remaining: this.#entries.length, outcome: 'offline' };
        }
        // The server refused it. Keeping it at the head of the queue would block every later
        // edit forever, so it is dropped and reported — the local state is still intact and the
        // next successful refresh reconciles it.
        this.#options.onDropped?.(entry, error);
      }
      this.#entries = this.#entries.slice(1);
      await this.#persist();
    }

    return { flushed, remaining: 0, outcome: 'done' };
  }

  #materialise(request: WriteRequest): QueuedWrite {
    const base = { id: this.#options.random(), at: this.#options.clock() };
    switch (request.kind) {
      case 'create':
        return { ...base, kind: 'create', noteId: request.noteId, input: request.input };
      case 'update':
        return { ...base, kind: 'update', noteId: request.noteId, patch: request.patch };
      case 'trash':
        return { ...base, kind: 'trash', noteId: request.noteId };
      case 'purge':
        return { ...base, kind: 'purge', noteId: request.noteId };
      default:
        return { ...base, kind: 'restore', noteId: request.noteId };
    }
  }

  async #enqueue(write: QueuedWrite): Promise<void> {
    const last = this.#entries.at(-1);
    if (
      write.kind === 'update' &&
      last !== undefined &&
      last.kind === 'update' &&
      last.noteId === write.noteId
    ) {
      // Two patches to the same note in a row are one patch. Later fields win, which is exactly
      // what applying them in order would have produced.
      const merged: QueuedWrite = {
        ...last,
        at: write.at,
        patch: { ...last.patch, ...write.patch },
      };
      this.#entries = [...this.#entries.slice(0, -1), merged];
    } else if (
      write.kind === 'create' &&
      this.#entries.some((entry) => entry.kind === 'create' && entry.noteId === write.noteId)
    ) {
      // A note is created once. A repeat is a retry, not a second note.
      return;
    } else {
      this.#entries = [...this.#entries, write];
    }
    await this.#persist();
  }

  async #persist(): Promise<void> {
    await this.#options.storage.set(this.#key, JSON.stringify(this.#entries));
    this.#emit();
  }

  #emit(): void {
    for (const listener of [...this.#listeners]) {
      listener(this.#entries);
    }
  }
}
