/**
 * Hash routing, hand-rolled.
 *
 * **Not a preference.** The dev site's nginx has no SPA history fallback and adding one needs
 * sudo this project does not have, so `/wip/notes/group/abc` would 404 on reload. A fragment is
 * never sent to the server, so `#/group/abc` cannot. Combined with `base: './'` in the Vite
 * config, the same build works at `/wip/notes/` and at whatever path it is promoted to.
 *
 * The router is a parser and a printer, because that is all a router is. Every route is a value,
 * every link is built with {@link routeToHash}, and an address nobody recognises becomes
 * `notFound` rather than a silent redirect that hides a broken link.
 *
 * ## The navigation model, in the route table
 *
 * **One column, any depth.** There is no route for "a level of the tree" — a group is a group
 * whether it is at the top or six deep, and `#/group/:id` is the whole of it. Depth lives in the
 * data, which is what lets the same three routes serve 1440px, 390px and a 320px editor panel
 * without a second model to learn. The breadcrumb and the spine read the ancestor chain out of
 * the group tree; neither needs the URL to remember how you arrived.
 */

/** Routes reachable without a session. Everything else goes through the guard. */
const PUBLIC_ROUTE_NAMES: ReadonlySet<string> = new Set([
  'signIn',
  'register',
  'forgotPassword',
  'resetPassword',
  // A share link has to work for somebody who has never had an account here — that is the whole
  // point of it — so the guard must not bounce it to the sign-in form.
  'share',
]);

export type Route =
  /** Every top-level group. The front door. */
  | { readonly name: 'home' }
  /** A group at any depth: its subgroups and its notes. */
  | { readonly name: 'group'; readonly groupId: string }
  /** A group's settings, as a screen of its own rather than a sheet over the group. */
  | { readonly name: 'groupSettings'; readonly groupId: string }
  /** The add-a-group flow. `parentId` is `null` at the top level, where presets are offered. */
  | { readonly name: 'newGroup'; readonly parentId: string | null }
  | { readonly name: 'note'; readonly noteId: string }
  | { readonly name: 'search'; readonly query: string }
  | { readonly name: 'trash' }
  | { readonly name: 'settings' }
  /** The starting points a new group is made from — the presets, and yours to edit. */
  | { readonly name: 'templates' }
  | { readonly name: 'template'; readonly templateId: string }
  /**
   * A shared note, opened by whoever was handed the link. `shareId` is the capability itself, so
   * it is short — `#/s/…` rather than `#/share/…` — and it lives in the fragment, which browsers
   * never put in a `Referer` header and never send to the server.
   */
  | { readonly name: 'share'; readonly shareId: string }
  /** `next` is the hash to return to once there is a session — how the guard remembers. */
  | { readonly name: 'signIn'; readonly next: string | null }
  | { readonly name: 'register'; readonly next: string | null }
  | { readonly name: 'forgotPassword' }
  | { readonly name: 'resetPassword'; readonly token: string }
  | { readonly name: 'notFound'; readonly path: string };

export type RouteName = Route['name'];

export const DEFAULT_ROUTE: Route = { name: 'home' };
export const SIGN_IN_ROUTE: Route = { name: 'signIn', next: null };

/** Can this address be reached without a session? */
export function isPublicRoute(route: Route): boolean {
  return PUBLIC_ROUTE_NAMES.has(route.name);
}

function param(params: URLSearchParams, key: string): string | null {
  const value = params.get(key);
  return value === null || value === '' ? null : value;
}

/** Parse a `location.hash`. Anything unrecognised is `notFound` rather than a silent redirect. */
export function parseRoute(hash: string): Route {
  const path = hash.replace(/^#/, '');
  if (path === '' || path === '/') {
    return DEFAULT_ROUTE;
  }

  const [pathname = '', queryString = ''] = path.split('?', 2);
  const segments = pathname.split('/').filter((segment) => segment !== '');
  const params = new URLSearchParams(queryString);

  const [head, second, third] = segments;

  if (segments.length === 1) {
    switch (head) {
      case 'home':
        return { name: 'home' };
      case 'search':
        return { name: 'search', query: params.get('q') ?? '' };
      case 'trash':
        return { name: 'trash' };
      case 'settings':
        return { name: 'settings' };
      case 'starting-points':
        return { name: 'templates' };
      case 'new-group':
        return { name: 'newGroup', parentId: param(params, 'in') };
      case 'sign-in':
        return { name: 'signIn', next: param(params, 'next') };
      case 'register':
        return { name: 'register', next: param(params, 'next') };
      case 'forgot-password':
        return { name: 'forgotPassword' };
      case 'reset-password':
        return { name: 'resetPassword', token: params.get('token') ?? '' };
      default:
        return { name: 'notFound', path: pathname };
    }
  }

  if (segments.length === 2 && second !== undefined) {
    switch (head) {
      case 'note':
        return { name: 'note', noteId: decodeURIComponent(second) };
      case 'group':
        return { name: 'group', groupId: decodeURIComponent(second) };
      case 'starting-points':
        return { name: 'template', templateId: decodeURIComponent(second) };
      case 's':
        return { name: 'share', shareId: decodeURIComponent(second) };
      default:
        return { name: 'notFound', path: pathname };
    }
  }

  // `#/group/:id/settings` — a screen of its own, and linkable, because "show me what this group
  // is set to" is a thing one person sends another.
  if (segments.length === 3 && head === 'group' && second !== undefined && third === 'settings') {
    return { name: 'groupSettings', groupId: decodeURIComponent(second) };
  }

  return { name: 'notFound', path: pathname };
}

/** The inverse of {@link parseRoute}. Every link in the app is built with this. */
export function routeToHash(route: Route): string {
  switch (route.name) {
    case 'home':
      return '#/home';
    case 'group':
      return `#/group/${encodeURIComponent(route.groupId)}`;
    case 'groupSettings':
      return `#/group/${encodeURIComponent(route.groupId)}/settings`;
    case 'newGroup':
      return route.parentId === null
        ? '#/new-group'
        : `#/new-group?in=${encodeURIComponent(route.parentId)}`;
    case 'note':
      return `#/note/${encodeURIComponent(route.noteId)}`;
    case 'search':
      return route.query === '' ? '#/search' : `#/search?q=${encodeURIComponent(route.query)}`;
    case 'trash':
      return '#/trash';
    case 'settings':
      return '#/settings';
    case 'templates':
      return '#/starting-points';
    case 'template':
      return `#/starting-points/${encodeURIComponent(route.templateId)}`;
    case 'share':
      return `#/s/${encodeURIComponent(route.shareId)}`;
    case 'signIn':
      return route.next === null ? '#/sign-in' : `#/sign-in?next=${encodeURIComponent(route.next)}`;
    case 'register':
      return route.next === null
        ? '#/register'
        : `#/register?next=${encodeURIComponent(route.next)}`;
    case 'forgotPassword':
      return '#/forgot-password';
    case 'resetPassword':
      return route.token === ''
        ? '#/reset-password'
        : `#/reset-password?token=${encodeURIComponent(route.token)}`;
    case 'notFound':
      return `#${route.path}`;
    default:
      return '#/home';
  }
}

export function routesEqual(left: Route, right: Route): boolean {
  return routeToHash(left) === routeToHash(right);
}

/**
 * The group a route belongs to, or `null`.
 *
 * Used for two things that both matter: which entry in Places is current, and which group's
 * colour the screen is painted in. A note's group is not in its URL, so the caller resolves that
 * from the group tree and passes it — this only answers for the routes that name one outright.
 */
export function routeGroupId(route: Route): string | null {
  switch (route.name) {
    case 'group':
    case 'groupSettings':
      return route.groupId;
    case 'newGroup':
      return route.parentId;
    default:
      return null;
  }
}

/** What the browser tab should say. Small, but a wall of open tabs is unusable without it. */
export function routeTitle(route: Route, groupName?: string | null): string {
  switch (route.name) {
    case 'home':
      return 'Notes';
    case 'group':
      return groupName === null || groupName === undefined ? 'Notes' : `${groupName} · Notes`;
    case 'groupSettings':
      return groupName === null || groupName === undefined
        ? 'Group settings · Notes'
        : `${groupName} settings · Notes`;
    case 'newGroup':
      return 'New group · Notes';
    case 'search':
      return route.query === '' ? 'Search · Notes' : `${route.query} · Search · Notes`;
    case 'trash':
      return 'Trash · Notes';
    case 'settings':
      return 'Settings · Notes';
    case 'templates':
    case 'template':
      return 'Starting points · Notes';
    case 'share':
      // Deliberately says nothing about *which* note: a tab title is visible over a shoulder and
      // ends up in browser history, and the share id is already enough of a secret to look after.
      return 'Shared note · Notes';
    case 'signIn':
    case 'register':
      return 'Sign in · Notes';
    case 'forgotPassword':
    case 'resetPassword':
      return 'Reset password · Notes';
    default:
      return 'Notes';
  }
}
