import { createContext, type ReactNode, useCallback, useContext, useMemo, useState } from 'react';
import { Icon, type IconName } from './icons';

/**
 * Toasts: confirm the thing that just happened, in the same words as the control.
 *
 * "Share with Ryla" is answered by "Shared." — same verb, no new vocabulary to map. A toast that
 * says "Success" has told nobody anything.
 *
 * `aria-live="polite"` rather than `assertive`: these confirm, they do not warn. Anything that
 * needs interrupting somebody mid-sentence is a callout or a dialog, not a toast.
 */

const TOAST_MS = 3_200;

export type ToastTone = 'default' | 'brass' | 'clay';

interface Toast {
  readonly id: number;
  readonly message: string;
  readonly tone: ToastTone;
  readonly icon: IconName;
}

export interface ToastControl {
  show(message: string, options?: { tone?: ToastTone; icon?: IconName }): void;
}

const ToastContext = createContext<ToastControl | null>(null);

export function useToast(): ToastControl {
  const value = useContext(ToastContext);
  // A toast is a courtesy, never a dependency: a component rendered outside the provider — a
  // share page, a test harness — should keep working rather than throw.
  return value ?? { show: () => undefined };
}

export function ToastProvider({ children }: { readonly children: ReactNode }): React.JSX.Element {
  const [toasts, setToasts] = useState<readonly Toast[]>([]);

  const show = useCallback<ToastControl['show']>((message, options = {}) => {
    const id = Date.now() + Math.random();
    const toast: Toast = {
      id,
      message,
      tone: options.tone ?? 'default',
      icon: options.icon ?? 'check',
    };
    setToasts((previous) => [...previous, toast]);
    globalThis.setTimeout(() => {
      setToasts((previous) => previous.filter((item) => item.id !== id));
    }, TOAST_MS);
  }, []);

  const control = useMemo<ToastControl>(() => ({ show }), [show]);

  return (
    <ToastContext.Provider value={control}>
      {children}
      <div aria-live="polite" className="toasts">
        {toasts.map((toast) => (
          <div
            className={toast.tone === 'default' ? 'toast' : `toast ${toast.tone}`}
            key={toast.id}
          >
            <Icon name={toast.icon} />
            <span>{toast.message}</span>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}
