/**
 * Where the API lives.
 *
 * Three sources, most specific first:
 *
 * 1. **A value the user typed**, kept in `localStorage`. The build is deployed by copying files;
 *    without this, pointing a deployed app at a different server would mean a rebuild, and
 *    "try it against your own instance" would mean cloning the repo.
 * 2. **`VITE_API_BASE_URL`** from the build environment — the normal path. It comes from a
 *    gitignored `.env`; `.env.example` carries a placeholder, never a real host.
 * 3. **Same origin**, which is what a reverse proxy in front of both would give.
 *
 * There is no hardcoded default host anywhere in this repo, and there must not be: the app is
 * public and the server it happens to talk to is not.
 */

const OVERRIDE_KEY = 'rosie-notes:api-base-url';

/** Reject anything that is not an absolute http(s) URL, or a same-origin path. */
export function normaliseBaseUrl(value: string): string | null {
  const trimmed = value.trim().replace(/\/+$/, '');
  if (trimmed === '') {
    return null;
  }
  if (trimmed.startsWith('/')) {
    return trimmed;
  }
  try {
    const url = new URL(trimmed);
    if (url.protocol !== 'https:' && url.protocol !== 'http:') {
      return null;
    }
    return url.origin + url.pathname.replace(/\/+$/, '');
  } catch {
    return null;
  }
}

export function readOverride(storage: Storage): string | null {
  const raw = storage.getItem(OVERRIDE_KEY);
  return raw === null ? null : normaliseBaseUrl(raw);
}

export function writeOverride(storage: Storage, value: string | null): void {
  if (value === null) {
    storage.removeItem(OVERRIDE_KEY);
    return;
  }
  storage.setItem(OVERRIDE_KEY, value);
}

export interface ResolvedApiConfig {
  readonly baseUrl: string;
  /** Where the value came from — shown in Settings so the source is never a mystery. */
  readonly source: 'override' | 'build' | 'origin';
}

export function resolveApiConfig(options: {
  storage: Storage;
  buildValue?: string | undefined;
  origin?: string | undefined;
}): ResolvedApiConfig {
  const override = readOverride(options.storage);
  if (override !== null) {
    return { baseUrl: override, source: 'override' };
  }

  const fromBuild = options.buildValue === undefined ? null : normaliseBaseUrl(options.buildValue);
  if (fromBuild !== null) {
    return { baseUrl: fromBuild, source: 'build' };
  }

  return { baseUrl: options.origin ?? '', source: 'origin' };
}

/** The app's configuration, resolved once at start-up. */
export function apiConfig(): ResolvedApiConfig {
  return resolveApiConfig({
    storage: globalThis.localStorage,
    buildValue: import.meta.env['VITE_API_BASE_URL'] as string | undefined,
    origin: globalThis.location?.origin,
  });
}
