import {
  ACCENT_NAMES,
  type AccentName,
  DEFAULT_HOVER_EMPHASIS,
  DENSITY_NAMES,
  type DensityName,
  HOVER_NAMES,
  type HoverEmphasis,
  type ThemeMode,
} from '@rosie-notes/tokens';
import { useCallback, useEffect, useState } from 'react';

/**
 * Theme, density, accent and hover emphasis — the four axes, persisted.
 *
 * The design system is deliberate about how few of these there are, and about theme having
 * *three* settings but *two* values: `system` is the third preference and it keeps following the
 * OS. Somebody whose machine switches at sunset expects the app to switch with it, and a one-shot
 * read at start-up does not do that.
 *
 * **Hover emphasis** is the fourth, and it is here rather than in a general settings bag because
 * it belongs to the same family: it changes how the app looks and nothing about what it holds, it
 * is per-device rather than per-account (the person with the poor monitor is not the account,
 * they are the machine), and it is one of the four attributes the stylesheet reads off the
 * wrapper. It is stored beside the others for exactly that reason.
 *
 * All four are written onto the app's own wrapper element rather than `<html>`, matching the
 * `[data-rn]` scope the tokens stylesheet declares into. `colorScheme` is the one thing that does
 * go on the document, because form controls and scrollbars are painted by the browser and only
 * read it from the root.
 */

const THEME_KEY = 'rosie-notes:theme';
const DENSITY_KEY = 'rosie-notes:density';
const ACCENT_KEY = 'rosie-notes:accent';
const HOVER_KEY = 'rosie-notes:hover';

export type ThemePreference = 'system' | ThemeMode;

function read(key: string): string | null {
  try {
    return globalThis.localStorage?.getItem(key) ?? null;
  } catch {
    // Private browsing, or storage disabled. Defaults apply and nothing is worth telling anyone.
    return null;
  }
}

function write(key: string, value: string | null): void {
  try {
    if (value === null) globalThis.localStorage?.removeItem(key);
    else globalThis.localStorage?.setItem(key, value);
  } catch {
    // The preference simply will not stick.
  }
}

function storedTheme(): ThemePreference {
  const stored = read(THEME_KEY);
  return stored === 'light' || stored === 'dark' ? stored : 'system';
}

function storedDensity(): DensityName {
  const stored = read(DENSITY_KEY);
  return DENSITY_NAMES.includes(stored as DensityName) ? (stored as DensityName) : 'roomy';
}

function storedAccent(): AccentName {
  const stored = read(ACCENT_KEY);
  return ACCENT_NAMES.includes(stored as AccentName) ? (stored as AccentName) : 'rose';
}

function storedHover(): HoverEmphasis {
  const stored = read(HOVER_KEY);
  return HOVER_NAMES.includes(stored as HoverEmphasis)
    ? (stored as HoverEmphasis)
    : DEFAULT_HOVER_EMPHASIS;
}

function systemTheme(): ThemeMode {
  return globalThis.matchMedia?.('(prefers-color-scheme: light)').matches === true
    ? 'light'
    : 'dark';
}

export interface Appearance {
  /** What is actually on screen. */
  readonly theme: ThemeMode;
  /** What was asked for, which may be `system`. */
  readonly themePreference: ThemePreference;
  readonly density: DensityName;
  readonly accent: AccentName;
  /** How loudly the thing under the pointer says so. */
  readonly hover: HoverEmphasis;
  setThemePreference(preference: ThemePreference): void;
  setDensity(density: DensityName): void;
  setAccent(accent: AccentName): void;
  setHover(hover: HoverEmphasis): void;
}

export function useAppearance(): Appearance {
  const [themePreference, setThemeState] = useState<ThemePreference>(storedTheme);
  const [system, setSystem] = useState<ThemeMode>(systemTheme);
  const [density, setDensityState] = useState<DensityName>(storedDensity);
  const [accent, setAccentState] = useState<AccentName>(storedAccent);
  const [hover, setHoverState] = useState<HoverEmphasis>(storedHover);

  // Follow the OS for as long as the preference is `system`. The listener is cheap and always
  // attached, so switching back to `system` needs no re-subscription.
  useEffect(() => {
    const query = globalThis.matchMedia?.('(prefers-color-scheme: light)');
    if (query === undefined || typeof query.addEventListener !== 'function') {
      return;
    }
    const onChange = (): void => setSystem(query.matches ? 'light' : 'dark');
    query.addEventListener('change', onChange);
    return () => query.removeEventListener('change', onChange);
  }, []);

  const theme: ThemeMode = themePreference === 'system' ? system : themePreference;

  // Only `color-scheme` reaches the document: it is what makes the browser paint native
  // scrollbars, date pickers and autofill in the right theme, and it is read from the root only.
  useEffect(() => {
    const root = globalThis.document?.documentElement;
    if (root === undefined) return;
    root.style.colorScheme = theme;
  }, [theme]);

  const setThemePreference = useCallback((next: ThemePreference) => {
    setThemeState(next);
    write(THEME_KEY, next === 'system' ? null : next);
  }, []);

  const setDensity = useCallback((next: DensityName) => {
    setDensityState(next);
    write(DENSITY_KEY, next === 'roomy' ? null : next);
  }, []);

  const setAccent = useCallback((next: AccentName) => {
    setAccentState(next);
    write(ACCENT_KEY, next === 'rose' ? null : next);
  }, []);

  const setHover = useCallback((next: HoverEmphasis) => {
    setHoverState(next);
    write(HOVER_KEY, next === DEFAULT_HOVER_EMPHASIS ? null : next);
  }, []);

  return {
    theme,
    themePreference,
    density,
    accent,
    hover,
    setThemePreference,
    setDensity,
    setAccent,
    setHover,
  };
}
