import type { ReactNode } from 'react';
import { Icon } from './icons';
import { Btn } from './primitives';

/**
 * The unglamorous states, written once.
 *
 * A blank screen is a bug that looks like a design decision, and a bare spinner is a promise with
 * no expiry date. Every screen in this app ends in one of these, so there is nowhere left for an
 * unexplained void to appear.
 *
 * The distinction that matters most is between **offline** and **failed**. A list drawn from the
 * cache is an *answer* — it is what this device last knew — and dressing it as an error teaches
 * people to distrust a correct screen. So the cached content stays visible and gains a banner;
 * only a request that failed with nothing to fall back on gets an error state.
 */

export interface EmptyStateProps {
  readonly title: string;
  readonly body?: ReactNode;
  /** The single big button. Empty screens are an invitation, not a mood. */
  readonly action?: ReactNode;
  /** A quiet second option, so the primary action stays singular. */
  readonly alt?: ReactNode;
}

export function EmptyState({ title, body, action, alt }: EmptyStateProps): React.JSX.Element {
  return (
    <div className="empty">
      <div className="empty-mark" />
      <h2>{title}</h2>
      {body !== undefined && <p>{body}</p>}
      {action}
      {alt !== undefined && <div className="empty-alt">{alt}</div>}
    </div>
  );
}

export interface LoadingStateProps {
  /** Say what is being waited for. "Loading…" on its own tells nobody anything. */
  readonly label: string;
}

export function LoadingState({ label }: LoadingStateProps): React.JSX.Element {
  return (
    <div aria-busy="true" className="screenstate is-loading" role="status">
      <span aria-hidden="true" className="spinner" />
      <p className="screenstate-body">{label}</p>
    </div>
  );
}

export interface ErrorStateProps {
  readonly title: string;
  readonly body?: ReactNode;
  readonly onRetry?: () => void;
}

export function ErrorState({ title, body, onRetry }: ErrorStateProps): React.JSX.Element {
  return (
    <div className="screenstate is-error" role="alert">
      <p className="screenstate-title">{title}</p>
      {body !== undefined && <p className="screenstate-body">{body}</p>}
      {onRetry !== undefined && (
        <div className="screenstate-action">
          <Btn onClick={onRetry} tone="ghost">
            Try again
          </Btn>
        </div>
      )}
    </div>
  );
}

/**
 * Permission denied, said as an audience question rather than a system one.
 *
 * "You do not have access" tells somebody nothing they can act on. Naming who *does* — and
 * offering the way back — is the difference between a dead end and a wrong turn.
 */
export function PermissionDeniedState({
  what = 'this',
  onBack,
}: {
  readonly what?: string;
  readonly onBack?: () => void;
}): React.JSX.Element {
  return (
    <div className="screenstate is-error" role="alert">
      <p className="screenstate-title">You cannot open {what}</p>
      <p className="screenstate-body">
        It belongs to someone who has not shared it with this account. If you think that is wrong,
        the person who owns it can share it from their own copy.
      </p>
      {onBack !== undefined && (
        <div className="screenstate-action">
          <Btn onClick={onBack} tone="ghost">
            Back to your groups
          </Btn>
        </div>
      )}
    </div>
  );
}

/** Something was asked for by address and is not there. Never a silent redirect. */
export function NotFoundState({
  what = 'That address',
  onBack,
}: {
  readonly what?: string;
  readonly onBack?: () => void;
}): React.JSX.Element {
  return (
    <div className="screenstate" role="status">
      <p className="screenstate-title">{what} does not lead anywhere</p>
      <p className="screenstate-body">
        It may have been trashed, moved, or the link may have been copied incompletely.
      </p>
      {onBack !== undefined && (
        <div className="screenstate-action">
          <Btn onClick={onBack} tone="ghost">
            Back to your groups
          </Btn>
        </div>
      )}
    </div>
  );
}

/** Content is on screen and it came from this device rather than the server. */
export function OfflineBanner({ what = 'this' }: { readonly what?: string }): React.JSX.Element {
  return (
    <p className="banner" role="status">
      <Icon name="cloudoff" />
      <span>
        Showing the {what} last saved on this device. Changes you make are kept and sent when the
        server is reachable again.
      </span>
    </p>
  );
}

/**
 * Writes are queued and waiting.
 *
 * Brass would be wrong here — brass means private — so this is the neutral banner with a count.
 * The number is the whole message: somebody who has been writing on a train wants to know how
 * much is still in the outbox, not to be reassured in general terms.
 */
export function PendingWritesBanner({ count }: { readonly count: number }): React.JSX.Element {
  return (
    <p className="banner" role="status">
      <Icon name="cloudoff" />
      <span>
        {count === 1 ? '1 change is' : `${count} changes are`} waiting to reach the server. They are
        saved on this device and will go out on their own.
      </span>
    </p>
  );
}

/** A sync attempt failed. Distinct from offline: the server answered, and said no. */
export function SyncFailedBanner({
  detail,
  onRetry,
}: {
  readonly detail?: string;
  readonly onRetry?: () => void;
}): React.JSX.Element {
  return (
    <p className="banner banner-clay" role="alert">
      <Icon name="warn" />
      <span>
        The last sync did not go through{detail === undefined ? '.' : `: ${detail}`} Nothing you
        wrote has been lost — it is still on this device.
      </span>
      {onRetry !== undefined && (
        <Btn onClick={onRetry} small tone="ghost">
          Retry
        </Btn>
      )}
    </p>
  );
}
