/*
 * The starting points a group can be made from used to be listed here as four constants.
 * They are not any more, and deliberately: since 2026-08-24 a preset is a **template the user
 * owns**, so its name, blurb and mark come from the server with their edits applied
 * (`useTemplates`). The shipped defaults live in `GROUP_PRESET_INFO` in the schema package,
 * because the server needs the same words when it has never stored a row.
 */

const SORT_LABELS: readonly { readonly sort: Sort; readonly label: string }[] = [
  { sort: { field: 'updatedAt', direction: 'desc' }, label: 'Recently changed' },
  { sort: { field: 'createdAt', direction: 'desc' }, label: 'Newest first' },
  { sort: { field: 'title', direction: 'asc' }, label: 'Alphabetical' },
  { sort: { field: 'position', direction: 'asc' }, label: 'Manual' },
  { sort: { field: 'lastSeenAt', direction: 'asc' }, label: 'Least read' },
];

export function sortLabel(sort: Sort): string {
  const found = SORT_LABELS.find(
    (entry) => entry.sort.field === sort.field && entry.sort.direction === sort.direction,
  );
  return found?.label ?? 'Recently changed';
}

export const SORT_OPTIONS = SORT_LABELS.map((entry) => ({
  value: `${entry.sort.field}:${entry.sort.direction}`,
  label: entry.label,
  sort: entry.sort,
}));

export function sortFromValue(value: string): Sort {
  const found = SORT_OPTIONS.find((option) => option.value === value);
  return found?.sort ?? { field: 'updatedAt', direction: 'desc' };
}

