/**
 * A group's settings, read back as a paragraph.
 *
 * This is the sentence at the top of a group's settings screen. It is deliberately prose: the
 * point is that somebody can read one paragraph instead of scanning fifteen rows to find out
 * what a group is. **Sharing is described as an audience, never as storage** — the product makes
 * no claim about encryption of any kind.
 */
export function settingsSentence(settings: GroupSettings, memberNames: readonly string[]): string {
  const parts: string[] = [];

  const shape = settings.codeProject.enabled
    ? 'A code project.'
    : settings.readingMode
      ? 'A reading shelf.'
      : settings.memberSections
        ? 'A shared space.'
        : 'A plain group.';
  parts.push(shape);

  if (settings.sharedWith === 'specific_people') {
    parts.push(
      memberNames.length > 0
        ? `Shared with ${listSentence(memberNames)}.`
        : 'Shared with specific people, once you add them.',
    );
  } else if (settings.sharedWith === 'anyone_with_link') {
    parts.push('Anyone holding the link can read it.');
  } else {
    parts.push('Only you can see it.');
  }

  if (settings.memberSections) parts.push('Everyone writes in their own section.');
  if (settings.privateNotes) parts.push('Any note here can be locked.');

  const kind = NEW_NOTE_LABEL[settings.newNoteKind].toLowerCase();
  parts.push(
    settings.autoTitle.enabled
      ? `New notes start as a ${kind}, named by rule.`
      : `New notes start as a ${kind}.`,
  );

  return parts.join(' ');
}

// -------------------------------------------------------------------------------------------
// Automatic titles
// -------------------------------------------------------------------------------------------

/**
 * Render a group's `autoTitle.template` — `Dream — {date}` and friends.
 *
 * The placeholders are rendered by whichever client creates the note; the server only stores the
 * rule. `now` is injectable so a test does not have to pick a day it will still pass on.
 */
export function renderAutoTitle(template: string, groupName: string, now = new Date()): string {
  return template
    .replaceAll('{group}', groupName)
    .replaceAll(
      '{date}',
      now.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }),
    )
    .replaceAll('{time}', now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }));
}

/**
 * `Dream — 16 August 2026`, then `Dream — 16 August 2026 (2)`, then `(3)`.
 *
 * This is `autoTitle.numberWhenRepeated`, which the settings screen promises as "Numbered when
 * there is more than one on the same day". Two dreams on one night are otherwise two rows a
 * person cannot tell apart in a list — which is the whole job of a title.
 *
 * The number is found by looking at what is *taken* rather than by counting, so deleting the
 * second of three does not produce a second `(3)`. Comparison is trimmed and case-insensitive
 * because the collision that matters is the one a reader would see, not the one `===` sees.
 */
export function numberedTitle(base: string, taken: Iterable<string>): string {
  const used = new Set<string>();
  for (const title of taken) {
    used.add(title.trim().toLocaleLowerCase());
  }
  if (!used.has(base.trim().toLocaleLowerCase())) {
    return base;
  }
  for (let n = 2; n < 1000; n += 1) {
    const candidate = `${base} (${n})`;
    if (!used.has(candidate.trim().toLocaleLowerCase())) {
      return candidate;
    }
  }
  return base;
}

/** Past this a derived title stops being a title and starts being the note again. */
const DERIVED_TITLE_MAX = 120;

/**
 * A title for a note that has none, taken from its first line.
 *
 * A note is identified by its title everywhere it is not open — the list, search, a `[[link]]`,
 * the breadcrumb — so a shelf of "Untitled, Untitled, Untitled" is a shelf you cannot use. Every
 * notes app worth the name does this, and it costs the writer nothing: it only ever fills a title
 * that is *empty*, so anything typed into the field, or written by a group's `autoTitle` rule,
 * wins and keeps winning.
 *
 * Returns `null` when there is nothing worth taking.
 */
export function titleFromBody(markdown: string): string | null {
  for (const raw of markdown.split('\n')) {
    // Markdown decoration is for the body; a title made of `##` and `>` reads as noise in a list.
    const line = raw
      .replace(/^\s{0,3}(#{1,6}\s+|>\s?|[-*+]\s+|\d+[.)]\s+)/u, '')
      .replace(/[*_`~]/gu, '')
      .trim();
    if (line === '') {
      continue;
    }
    if (line.length <= DERIVED_TITLE_MAX) {
      return line;
    }
    // Cut on a word boundary if there is one near the end, so a long first line does not become
    // a title that stops mid-word.
    const cut = line.slice(0, DERIVED_TITLE_MAX);
    const space = cut.lastIndexOf(' ');
    return `${(space > DERIVED_TITLE_MAX - 24 ? cut.slice(0, space) : cut).trimEnd()}…`;
  }
  return null;
}

/** `a`, `a and b`, `a, b and c`. */
export function listSentence(items: readonly string[]): string {
  if (items.length === 0) return '';
  if (items.length === 1) return items[0] as string;
  return `${items.slice(0, -1).join(', ')} and ${items.at(-1) as string}`;
}

export function plural(count: number, word: string, pluralForm?: string): string {
  return `${count} ${count === 1 ? word : (pluralForm ?? `${word}s`)}`;
}

/** A relative time, in the words a person would use. Falls back to a date past a week. */
export function ago(iso: string | null): string {
  if (iso === null) return 'never';
  const then = Date.parse(iso);
  if (Number.isNaN(then)) return 'never';
  const seconds = Math.round((Date.now() - then) / 1000);
  if (seconds < 45) return 'just now';
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.round(hours / 24);
  if (days < 7) return `${days}d ago`;
  return new Date(then).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
}

/** `Untitled` rather than an empty row: a note with no title still has to be clickable. */
export function displayTitle(title: string): string {
  const trimmed = title.trim();
  return trimmed === '' ? 'Untitled' : trimmed;
}

/** A short, relative-ish timestamp. Long enough to be unambiguous, short enough for a list. */
export function shortWhen(iso: string, now: number = Date.now()): string {
  const at = new Date(iso);
  const days = (now - at.getTime()) / 86_400_000;
  if (Number.isNaN(days)) {
    return '';
  }
  if (days < 1) {
    return at.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
  }
  if (days < 365) {
    return at.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
  }
  return at.toLocaleDateString(undefined, { year: 'numeric', month: 'short' });
}

export function fullDate(iso: string): string {
  const parsed = Date.parse(iso);
  if (Number.isNaN(parsed)) return '';
  return new Date(parsed).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  });
}
