/**
 * The icon set, drawn once into a hidden sprite and referenced by `<use>`.
 *
 * Inline SVG rather than an icon font or a package: a strict CSP blocks every external host, and
 * an icon font would need one. Drawing each path once and referencing it means a list of two
 * hundred rows carries two hundred `<use>` elements rather than two hundred copies of the same
 * geometry.
 *
 * Every icon is stroked with `currentColor` at a single weight, so an icon inside a brass chip is
 * brass and an icon inside an accent button is accent ink, with nothing to keep in sync.
 */

export type IconName =
  | 'chev'
  | 'chevl'
  | 'chevd'
  | 'lock'
  | 'unlock'
  | 'plus'
  | 'search'
  | 'shuffle'
  | 'gear'
  | 'home'
  | 'book'
  | 'people'
  | 'check'
  | 'x'
  | 'warn'
  | 'edit'
  | 'doc'
  | 'cloud'
  | 'cloudoff'
  | 'sun'
  | 'moon'
  | 'dots'
  | 'tag'
  | 'trash'
  | 'eye'
  | 'eyeoff'
  | 'page'
  | 'flask'
  | 'term'
  | 'leaf'
  | 'map'
  | 'star'
  | 'heart'
  | 'spark'
  | 'clock'
  | 'box'
  | 'pin'
  | 'image'
  | 'palette'
  | 'move'
  | 'back';

export interface IconProps {
  readonly name: IconName;
  readonly className?: string;
}

/** One icon. Always `aria-hidden` — the accessible name lives on the control that holds it. */
export function Icon({ name, className }: IconProps): React.JSX.Element {
  return (
    <svg aria-hidden="true" className={className === undefined ? 'ico' : `ico ${className}`}>
      <use href={`#i-${name}`} />
    </svg>
  );
}

