/**
 * A very small IndexedDB wrapper.
 *
 * Deliberately not a library. The app needs three operations on two object stores, and every
 * IndexedDB wrapper worth using is larger than the code it would replace here. What it *does*
 * add is the two things hand-rolled IndexedDB usually gets wrong: every request is a promise
 * that rejects rather than a callback that silently does nothing, and a transaction is awaited
 * on `complete` rather than on the last request — those are not the same moment, and treating
 * them as one is how a write appears to succeed and then is not there after a reload.
 */

export const DATABASE_NAME = 'rosie-notes';
export const DATABASE_VERSION = 1;

/** Note metadata, keyed by note id. What the list and search views read. */
export const NOTES_STORE = 'notes';
/** Yjs document state, keyed by note id. Only the editor and the sync engine touch it. */
export const DOCS_STORE = 'docs';

function promisify<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('IndexedDB request failed'));
  });
}

/** Resolves when the transaction has actually committed, not when its last request returned. */
function committed(transaction: IDBTransaction): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onabort = () => reject(transaction.error ?? new Error('Transaction aborted'));
    transaction.onerror = () => reject(transaction.error ?? new Error('Transaction failed'));
  });
}

export function openDatabase(
  factory: IDBFactory,
  name = DATABASE_NAME,
  version = DATABASE_VERSION,
): Promise<IDBDatabase> {
  return new Promise<IDBDatabase>((resolve, reject) => {
    const request = factory.open(name, version);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(NOTES_STORE)) {
        db.createObjectStore(NOTES_STORE);
      }
      if (!db.objectStoreNames.contains(DOCS_STORE)) {
        db.createObjectStore(DOCS_STORE);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('Could not open the local cache'));
    request.onblocked = () =>
      reject(new Error('The local cache is open in another tab running an older version'));
  });
}

export async function idbGet<T>(db: IDBDatabase, store: string, key: string): Promise<T | null> {
  const transaction = db.transaction(store, 'readonly');
  const result = await promisify<T | undefined>(
    transaction.objectStore(store).get(key) as IDBRequest<T | undefined>,
  );
  return result ?? null;
}

export async function idbPut(
  db: IDBDatabase,
  store: string,
  key: string,
  value: unknown,
): Promise<void> {
  const transaction = db.transaction(store, 'readwrite');
  transaction.objectStore(store).put(value, key);
  await committed(transaction);
}

export async function idbDelete(db: IDBDatabase, store: string, key: string): Promise<void> {
  const transaction = db.transaction(store, 'readwrite');
  transaction.objectStore(store).delete(key);
  await committed(transaction);
}

export async function idbGetAll<T>(db: IDBDatabase, store: string): Promise<T[]> {
  const transaction = db.transaction(store, 'readonly');
  return promisify<T[]>(transaction.objectStore(store).getAll() as IDBRequest<T[]>);
}

export async function idbClear(db: IDBDatabase, stores: readonly string[]): Promise<void> {
  const transaction = db.transaction([...stores], 'readwrite');
  for (const store of stores) {
    transaction.objectStore(store).clear();
  }
  await committed(transaction);
}
