import type { CollectionId, Note, NoteId, TagName } from '@rosie-notes/schema';
import type { ThemeMode } from '@rosie-notes/tokens';
import { useCallback, useEffect, useState } from 'react';
import { useGroups } from '../hooks/use-groups';
import { useNoteActions } from '../hooks/use-note-actions';
import { useNote } from '../hooks/use-store';
import { useNavigate } from '../routing/use-route';
import { Breadcrumb } from './chrome';
import { Icon } from './icons';
import { ago, fullDate, NOTE_KIND_LABEL } from './labels';
import { NoteEditor, type SaveState } from './note-editor';
import { Btn, Chip, Glyph, Sep, Switch } from './primitives';
import { useShell } from './shell-context';
import { ErrorState, LoadingState, NotFoundState, PermissionDeniedState } from './states';
import { useToast } from './toasts';

/**
 * One note: its title, its body, and the two controls that matter on it.
 *
 * The body is the **shared editor bundle** from `packages/editor`, mounted over the very `Y.Doc`
 * the sync engine already owns — so a keystroke goes editor → host → outbox → server with no code
 * in between, and a change from another device arrives by the same path backwards. Nothing about
 * that is web-specific, which is why the same bundle serves the phone and the VSCode panel.
 *
 * Reading mode is not a switch on this screen. It is a **group setting**, so a story opens as a
 * reading surface and a project doc does not, and there is no mode to get stuck in.
 */

export interface NoteViewProps {
  readonly noteId: string;
  readonly theme: ThemeMode;
}

export function NoteView({ noteId, theme }: NoteViewProps): React.JSX.Element {
  const { note, loading, error } = useNote(noteId as NoteId);
  const tree = useGroups();
  const navigate = useNavigate();
  const actions = useNoteActions();
  const toast = useToast();
  const shell = useShell();
  const [saveState, setSaveState] = useState<SaveState>('idle');
  const [title, setTitle] = useState('');

  // The title field is uncontrolled between renders — retyping it from the store on every
  // keystroke would fight the caret — so it is seeded when the note arrives and when it changes
  // underneath us, and otherwise left alone.
  useEffect(() => {
    if (note !== null) setTitle(note.title);
  }, [note]);

  const onOpenNote = useCallback(
    (linked: NoteId) => navigate({ name: 'note', noteId: linked as string }),
    [navigate],
  );

  const onCreateNote = useCallback(
    (linkTitle: string) => {
      void (async () => {
        const created = await actions.create({
          title: linkTitle,
          parentId: noteId as NoteId,
          ...(note === null || note.collectionIds.length === 0
            ? {}
            : { collectionIds: [...note.collectionIds] }),
        });
        navigate({ name: 'note', noteId: created as string });
      })();
    },
    [actions, navigate, noteId, note],
  );

  if (loading && note === null) {
    return <LoadingState label="Opening the note…" />;
  }

  if (error !== null && note === null) {
    // A 403 is a different sentence from a 404: one says it is not yours, the other says it is
    // not there, and telling somebody the wrong one wastes their time.
    const status = (error as { status?: number }).status;
    if (status === 403) {
      return <PermissionDeniedState onBack={() => navigate({ name: 'home' })} what="this note" />;
    }
    if (status === 404) {
      return <NotFoundState onBack={() => navigate({ name: 'home' })} what="That note" />;
    }
    return (
      <ErrorState
        body="The server did not answer and this device has no copy of it."
        title="This note could not be opened"
      />
    );
  }

  if (note === null) {
    return <NotFoundState onBack={() => navigate({ name: 'home' })} what="That note" />;
  }

  const groupId = (note.collectionIds[0] as string | undefined) ?? null;
  const group = groupId === null ? undefined : tree.byId.get(groupId);
  const settings = tree.settingsOf(groupId).effective;
  const isPrivate = note.tags.includes('private' as TagName);

  function commitTitle(): void {
    const trimmed = title.trim();
    if (note === null || trimmed === note.title) return;
    void actions.rename(note.id, trimmed);
  }

  function toggleLock(next: boolean): void {
    if (note === null) return;
    const tags = next
      ? [...note.tags, 'private' as TagName]
      : note.tags.filter((tag) => tag !== 'private');
    void actions.setTags(note.id, tags).then(() => {
      toast.show(next ? 'Locked.' : 'Unlocked.', {
        tone: 'brass',
        icon: next ? 'lock' : 'unlock',
      });
    });
  }

  return (
    <>
      <Breadcrumb
        chain={tree.chain(groupId)}
        leaf={note.title === '' ? 'Untitled' : note.title}
        onHome={() => navigate({ name: 'home' })}
        onOpen={(ancestor) => navigate({ name: 'group', groupId: ancestor.id as string })}
      />

      <div className="note-head">
        <div className="glyph">
          <Glyph icon={null} />
        </div>
        <div className="note-head-main">
          <input
            aria-label="Note title"
            className="note-title"
            onBlur={commitTitle}
            onChange={(event) => setTitle(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') event.currentTarget.blur();
            }}
            placeholder="Untitled"
            value={title}
          />
          <div className="psub">
            <Chip>{NOTE_KIND_LABEL[note.kind]}</Chip>
            {isPrivate && (
              <Chip icon="lock" tone="private">
                Private
              </Chip>
            )}
            <span className="num">Created {fullDate(note.createdAt)}</span>
            <Sep />
            <span className="num">Updated {ago(note.updatedAt)}</span>
          </div>
        </div>
      </div>

      <div className="editbar">
        <Btn icon="move" onClick={() => shell.openMove(noteId)} small tone="quiet">
          Move
        </Btn>
        <Btn
          icon="trash"
          onClick={() => {
            void actions.trash(note.id).then(() => {
              toast.show('Moved to trash.', { icon: 'trash' });
              navigate(groupId === null ? { name: 'home' } : { name: 'group', groupId }, {
                replace: true,
              });
            });
          }}
          small
          tone="quiet"
        >
          Move to trash
        </Btn>
        <span className={saveStateClass(saveState)}>
          <Icon name={saveState === 'offline' ? 'cloudoff' : 'cloud'} />
          <span>{SAVE_LABEL[saveState]}</span>
        </span>
      </div>

      <NoteEditor
        noteId={note.id}
        onCreateNote={onCreateNote}
        onOpenNote={onOpenNote}
        onSaveStateChange={setSaveState}
        reading={settings.readingMode}
        theme={theme}
      />

      {/* The highest-stakes control in the product, so it gets real estate rather than a menu.
          The copy names *who can see it* and never says anything about how it is stored. */}
      {group !== undefined && settings.privateNotes && (
        <div className={isPrivate ? 'privacy on' : 'privacy'}>
          <Icon name={isPrivate ? 'lock' : 'unlock'} />
          <div className="privacy-main">
            <div className="privacy-t">
              {isPrivate ? 'Private — only you' : `Visible to everyone in ${group.name}`}
            </div>
            <div className="privacy-d">
              {isPrivate
                ? `Hidden from everyone else in ${group.name}. Whoever runs the server can still read it.`
                : `Anyone this group is shared with can read this. Lock it and only you will see it.`}
            </div>
          </div>
          <Switch checked={isPrivate} label="Private" onChange={toggleLock} />
        </div>
      )}
    </>
  );
}

const SAVE_LABEL: Record<SaveState, string> = {
  idle: 'Saved',
  dirty: 'Unsaved…',
  saving: 'Saving…',
  saved: 'Saved',
  offline: 'Waiting for the server',
  error: 'Could not save',
};

function saveStateClass(state: SaveState): string {
  if (state === 'offline') return 'state is-offline';
  if (state === 'error') return 'state is-error';
  return 'state';
}

/** Where a note lives, for the move picker and the context column. */
export function noteGroupId(note: Note): CollectionId | null {
  return (note.collectionIds[0] as CollectionId | undefined) ?? null;
}
